import type {CaseStory} from "./case-lab-story";

/**
 * Authored case files for every non-deep case in the 50-case launch collection.
 * Every record has its own patient profile, history, findings, differential logic,
 * management, follow-up plan and condition-relevant evidence link. These are
 * educational simulations, not real patient records or individualized advice.
 */
type Ref={title:string;organization:string;year?:string;url:string};
type Episode={
 id:string;category:string;patient:string;opening:string;scene:string[];
 history:[string,string][];findings:string[];examPrompt:string;examReason:string;
 diagnosis:string;diagnosisReason:string;differentials:{diagnosis:string;reasoning:string}[];
 management:string[];progression:string[];learning:string[];urgent?:boolean;references:Ref[];
};
const nice=(title:string,url:string,year="Current"):Ref=>({title,organization:"NICE",year,url});
const aaos=(title:string,url:string):Ref=>({title,organization:"American Academy of Orthopaedic Surgeons",year:"Clinical guidance",url});
const jn=(title:string,term:string):Ref=>({title,organization:"PubMed literature search",year:"Evidence search",url:"https://pubmed.ncbi.nlm.nih.gov/?term="+encodeURIComponent(term)});
const episodes:Episode[]=[
{id:"shoulder-01",category:"MSK & Sports",patient:"Imran Siddiqui, 52 · accounts officer",opening:"For four months my right shoulder has become so stiff that reaching behind my back or putting on a shirt is difficult.",scene:["Imran books an appointment because dressing and reaching a wallet from his back pocket have gradually become difficult. There was no fall or sudden loss of strength.","He has type 2 diabetes, controlled with his usual care. He denies fever, unexplained weight loss, chest symptoms or new neck-related arm symptoms."],history:[["When did the problem begin, and was there an injury?","It crept up over four months. I cannot name one injury."],["What movements are most limited?","Reaching behind my back and rotating the arm outward are the worst."],["Any numbness, fever, unexplained weight loss or severe night pain unrelated to position?","No numbness, fever or weight loss. It aches at night if I roll onto it."]],findings:["Both active and passive glenohumeral movement are restricted, with external rotation most limited.","The restriction is gradual and occurs in more than one movement plane; this is not simply pain-limited active elevation.","No focal neurological deficit or acute traumatic deformity is identified."],examPrompt:"Which pattern best separates a stiff glenohumeral joint from isolated rotator-cuff-related pain?",examReason:"Concordant loss of active and passive range, especially external rotation, supports an adhesive-capsulitis pattern. Check cervical contribution, systemic features and whether restriction is disproportionate or atypical.",diagnosis:"Probable adhesive capsulitis (frozen shoulder), with stage and irritability still to be characterized",diagnosisReason:"The gradual course and global active-plus-passive restriction fit adhesive capsulitis better than an isolated cuff pain presentation. Diabetes is a relevant association, not proof. Consider glenohumeral osteoarthritis and other causes of a stiff shoulder; refer for medical review if the presentation is atypical or deteriorating.",differentials:[{diagnosis:"Glenohumeral osteoarthritis",reasoning:"Can also cause global passive restriction; age, crepitus, radiographic context and overall pattern may help distinguish it."},{diagnosis:"Rotator-cuff-related shoulder pain",reasoning:"Often limits active/resisted movement through pain while passive range is comparatively preserved; overlap can occur."}],management:["Explain the likely pattern and agree a meaningful goal such as dressing independently; avoid promising a rapid cure.","Match mobility work and exercise to irritability: gentle, tolerable movement when highly painful, progressing loading and range as symptoms allow.","Discuss sleep positioning and activity modification without prolonged immobilization; coordinate medical review for diagnostic uncertainty, severe symptoms or unmet analgesia needs."],progression:["Record baseline pain, active/passive range and a patient-specific task; reassess the same measures rather than relying on pain alone.","Progress intensity only when the response is acceptable and function is improving; reconsider diagnosis if the expected pattern does not emerge."],learning:["A stiff shoulder needs active and passive range comparison, not a single special test.","The likely diagnosis does not remove the need to screen for serious or referred causes.","Treatment dose should reflect irritability and the patient's functional priorities."],references:[aaos("Shoulder conditions: clinical practice guideline resources","https://www.aaos.org/quality/quality-programs/upper-extremity-programs/"),jn("Adhesive capsulitis: diagnosis and rehabilitation evidence","adhesive capsulitis clinical practice guideline physical therapy")]},
{id:"hand-01",category:"MSK & Sports",patient:"Sana Malik, 46 · bank clerk",opening:"At night my thumb, index and middle fingers go numb. Shaking my hand helps for a little while.",scene:["Sana's symptoms wake her several nights each week and she has started dropping coins at work. There was no acute wrist injury.","The aim is to establish the distribution and functional impact, screen for progressive nerve deficit and consider proximal or systemic contributors."],history:[["Which fingers are affected?","Mostly thumb, index and middle fingers, sometimes the radial half of the ring finger."],["What makes it better or worse?","It is worse at night and when holding my phone; shaking the hand helps briefly."],["Any constant numbness, weakness, neck pain or symptoms in the little finger?","No neck pain. The little finger is fine, but I sometimes struggle with buttons."]],findings:["Symptoms follow a median-nerve distribution and are worse at night.","Screen pinch, thumb abduction, thenar bulk and sensation; document any persistent sensory loss or weakness.","A provocative wrist test may reproduce symptoms but cannot independently confirm or exclude carpal tunnel syndrome."],examPrompt:"What combination of history and examination is most informative?",examReason:"Distribution, night symptoms, functional weakness and objective sensory/motor findings are more useful together than treating one provocative test as definitive. Consider cervical radiculopathy, proximal median neuropathy and polyneuropathy when the pattern is atypical.",diagnosis:"Suspected carpal tunnel syndrome affecting the median nerve at the wrist",diagnosisReason:"Nocturnal median-distribution paresthesia with relief by shaking is characteristic, but severity and alternative causes must be assessed before choosing treatment.",differentials:[{diagnosis:"Cervical radiculopathy",reasoning:"Look for neck-related symptoms and concordant myotomal, reflex or dermatomal findings beyond the median territory."},{diagnosis:"Ulnar neuropathy",reasoning:"Little-finger and ulnar-ring-finger symptoms point away from an isolated median nerve problem."}],management:["Explain the likely nerve-compression pattern and reduce sustained wrist positions that reproduce symptoms.","A neutral-position night splint may be reasonable for mild-to-moderate symptoms; discuss suitability and review response.","Arrange medical assessment for persistent symptoms, objective weakness/thenar wasting, constant sensory loss or diagnostic uncertainty; progressive deficit warrants prompt review."],progression:["Track night waking, hand function and objective sensation/strength; escalate if deficits progress or conservative care fails.","Return to the differential if the distribution becomes atypical or symptoms extend beyond the median nerve."],learning:["Map symptoms before naming the nerve lesion.","Provocative tests are not stand-alone diagnostic proof.","Persistent motor loss changes urgency and management."],references:[jn("Carpal tunnel syndrome diagnosis and conservative management","carpal tunnel syndrome clinical practice guideline diagnosis splinting"),aaos("Management of carpal tunnel syndrome","https://www.aaos.org/quality/quality-programs/upper-extremity-programs/carpal-tunnel-syndrome/")]},
{id:"back-01",category:"MSK & Sports",patient:"Tariq Mehmood, 35 · warehouse supervisor",opening:"After lifting a heavy box, pain spread from my lower back into the buttock. Repeated bending backward brings the buttock pain closer to my back.",scene:["Tariq wants to resume warehouse duties. Symptoms began during lifting but there is no reported major trauma.","Before movement testing, screen for serious pathology, cauda-equina symptoms, progressive neurological deficit and systemic risk. A directional response is a finding, not a structural diagnosis."],history:[["Does pain travel below the knee, and is there numbness or weakness?","Mostly buttock pain; no persistent numbness or new weakness."],["Any new bladder/bowel change, saddle numbness, fever, cancer history or unexplained weight loss?","No."],["What happens with repeated movement?","With repeated extension, the buttock ache eases and moves closer to the spine."]],findings:["Repeated lumbar extension reduces distal buttock symptoms and shifts symptoms proximally (centralization).","No progressive neurological deficit is reported in this teaching presentation.","The movement response should be repeated and documented alongside function and safety screening."],examPrompt:"How should the centralizing response influence the next step?",examReason:"Centralization can help identify a directional preference and guide a tolerable exercise trial; it does not prove a disc lesion or replace red-flag screening.",diagnosis:"Mechanical low-back pain with a centralizing directional response",diagnosisReason:"The reproducible proximal shift of symptoms during repeated movement supports a directional preference. Avoid overclaiming a specific anatomical source; diagnosis remains provisional and should fit the whole assessment.",differentials:[{diagnosis:"Lumbar radiculopathy",reasoning:"Assess myotomes, dermatomes, reflexes and neural symptoms if pain extends below the knee or neurological symptoms appear."},{diagnosis:"Serious spinal pathology",reasoning:"New bladder/bowel dysfunction, saddle sensory change, progressive weakness, systemic illness or significant trauma requires urgent medical assessment."}],management:["Explain the observed response and trial repeated movements in the direction that centralizes symptoms, provided the response remains safe and tolerable.","Maintain appropriate activity and build back toward work tasks; avoid prolonged bed rest and unnecessary fear-based restrictions.","Give explicit safety-net advice about new neurological or systemic symptoms; refer if red flags emerge."],progression:["Record distal symptom extent, pain, function and work tolerance before and after the trial.","Progress lifting exposure gradually; stop and reassess if symptoms peripheralize persistently or new neurological findings develop."],learning:["Centralization is a clinical response, not an anatomical diagnosis.","Screening comes before choosing a movement strategy.","Measure functional change, not just the direction of pain."],references:[nice("Low back pain and sciatica in over 16s (NG59)","https://www.nice.org.uk/guidance/ng59/chapter/recommendations","Updated 2020"),nice("Suspected neurological conditions: recognition and referral (NG127)","https://www.nice.org.uk/guidance/ng127/chapter/Recommendations-for-adults-aged-over-16")]},
{id:"ankle-01",category:"MSK & Sports",patient:"Bilal Ahmed, 21 · college basketball player",opening:"I landed on another player's foot, my ankle rolled inward and the outside swelled quickly.",scene:["Bilal is assessed the morning after a basketball landing injury. He can take a few steps but limps and wants to know whether imaging is needed.","Do not label every inversion injury a simple sprain before screening fracture, syndesmotic injury and neurovascular compromise."],history:[["Could you continue playing, and can you walk four steps now and just after the injury?","I stopped playing. I can take four painful steps."],["Where is the most tender point?","Mostly in front of and below the outer ankle bone."],["Any numbness, deformity or pain above the ankle?","No numbness or deformity; pain is mostly lateral."]],findings:["Lateral ankle swelling and tenderness around the anterior talofibular ligament region.","Pain with inversion loading; document weight-bearing ability and precise bony tenderness.","Neurovascular status is intact in this simulation; assess the malleoli, navicular and base of fifth metatarsal using an appropriate fracture decision rule."],examPrompt:"What must be checked before deciding that imaging is unnecessary?",examReason:"Ottawa Ankle Rules can help determine the need for radiography when applied correctly, including bony tenderness and ability to bear weight. They do not assess every injury type or replace clinical judgement.",diagnosis:"Likely lateral ankle ligament sprain; grade and associated injury require assessment",diagnosisReason:"The inversion mechanism and lateral ligament-region findings fit a lateral sprain, but fracture and syndesmotic injury must be considered before routine rehabilitation.",differentials:[{diagnosis:"Malleolar or fifth-metatarsal fracture",reasoning:"Focal bony tenderness or inability to take four steps under the rule's criteria indicates radiographic assessment."},{diagnosis:"Syndesmotic ankle injury",reasoning:"Pain above the ankle after external rotation or dorsiflexion loading, with distal tibiofibular tenderness, changes the assessment and expected recovery."}],management:["Use an appropriate Ottawa-rule assessment and arrange imaging/medical review when indicated; do not force stress tests through severe acute pain.","For a sprain after fracture concerns are addressed, use protected progressive weight bearing, external support when appropriate and early tolerable range of motion.","Progressive strength, balance and hopping/landing work should match the athlete's functional deficits and sport demands."],progression:["Reassess swelling, gait, range, calf strength, balance and confidence; compare with the demands of basketball rather than pain alone.","Return to sport only after function, hopping/landing and sport-specific tasks are tolerated without meaningful symptom flare."],learning:["Mechanism suggests a diagnosis but does not exclude fracture.","Use validated decision rules as intended.","Return-to-sport decisions need functional testing and graded exposure."],references:[jn("Lateral ankle sprain clinical practice guideline rehabilitation","lateral ankle ligament sprain clinical practice guideline physical therapy"),aaos("Foot and ankle injury information","https://orthoinfo.aaos.org/en/diseases--conditions/sprained-ankle/")]},
{id:"hip-01",category:"MSK & Sports",patient:"Ayesha Bibi, 49 · school teacher",opening:"The outside of my right hip hurts when I lie on it, and stairs are painful when I put my weight through that side.",scene:["Ayesha's symptoms have built up over several months and disturb sleep. She has no fall or sudden inability to bear weight.","The examination should distinguish lateral hip tendon-related pain from groin-dominant joint disease, lumbar referral and fracture/systemic concerns."],history:[["Where is the pain strongest?","At the bony outside of the hip, not deep in the groin."],["What loads it?","Lying on that side, climbing stairs and standing on one leg."],["Any recent trauma, fever, cancer history or inability to bear weight?","No." ]],findings:["Focal tenderness over the greater trochanter with familiar lateral pain.","Resisted hip abduction reproduces concordant pain.","No dominant groin pain or acute weight-bearing failure is reported."],examPrompt:"Which symptom and loading pattern supports a greater-trochanteric pain presentation?",examReason:"Lateral pain, focal tenderness and pain with hip-abductor loading support greater trochanteric pain syndrome (GTPS). No single sign proves a specific tendon lesion; screen lumbar and intra-articular contributors.",diagnosis:"Probable greater trochanteric pain syndrome",diagnosisReason:"The location and abductor-load response fit GTPS more than isolated hip osteoarthritis, while recognizing that overlapping conditions are possible.",differentials:[{diagnosis:"Hip osteoarthritis",reasoning:"Groin-dominant pain, stiffness and restricted hip internal rotation may support an intra-articular source."},{diagnosis:"Lumbar referred pain",reasoning:"Spinal movement or neurological findings that reproduce the familiar pain may indicate a concurrent or alternative contributor."}],management:["Explain the load-sensitive lateral hip pattern and reduce sustained compression, such as lying directly on the painful side, while maintaining tolerable activity.","Use progressive hip-abductor strengthening and functional loading, adjusted to symptom irritability rather than repeatedly provoking a severe flare.","Refer for medical review if there is trauma, rapid deterioration, unexplained systemic features or inability to bear weight."],progression:["Track sleep tolerance, stair function, single-leg loading and strength over time.","Increase load gradually and reassess the diagnosis if symptoms or findings do not respond as expected."],learning:["Pain location and load response guide—but do not independently prove—the diagnosis.","GTPS management usually needs load modification and progressive exercise, not just passive treatment.","Check the hip, lumbar spine and red flags together."],references:[jn("Greater trochanteric pain syndrome clinical management","greater trochanteric pain syndrome education exercise randomized trial"),nice("Osteoarthritis in over 16s: diagnosis and management (NG226)","https://www.nice.org.uk/guidance/ng226/chapter/Recommendations")]},
{id:"neck-01",category:"MSK & Sports",patient:"Ravi Kumar, 41 · delivery supervisor",opening:"Pain travels from my neck into my right arm, with tingling. Some neck positions make the arm symptoms worse.",scene:["Ravi spends long periods driving and lifting parcels. He reports arm symptoms but no trauma.","Assess neurological distribution and severity, screen for myelopathy and progressive deficit, and avoid assuming all arm pain comes from a cervical nerve root."],history:[["Which parts of the arm are affected?","The tingling reaches the thumb side of my hand."],["Any weakness, dropping objects, balance change or bladder/bowel symptoms?","My grip feels a little weaker, but no balance or bladder change."],["What changes the arm symptoms?","Turning and extending my neck sometimes increases the tingling."]],findings:["Sensory change follows a plausible dermatomal pattern with corresponding myotomal weakness in the simulated exam.","A compatible cervical provocation manoeuvre reproduces familiar arm symptoms; this is interpreted with the full neurological examination.","Screen reflexes, upper-motor-neuron signs, gait, bilateral symptoms and progression."],examPrompt:"What makes a cervical radiculopathy hypothesis more credible than local shoulder or wrist pain?",examReason:"Concordant arm symptoms with matching sensory, motor and/or reflex changes support nerve-root involvement. No single provocation test confirms it; progressive weakness or myelopathy signs require prompt escalation.",diagnosis:"Probable cervical radiculopathy; neurological severity and trajectory must be documented",diagnosisReason:"Radiating arm symptoms and concordant neurological findings are more consistent with cervical nerve-root involvement than isolated muscle soreness. Reassess urgently if weakness progresses or cord signs appear.",differentials:[{diagnosis:"Peripheral median neuropathy",reasoning:"A distal nerve distribution and wrist-related provocation without matching cervical findings may indicate entrapment."},{diagnosis:"Cervical myelopathy",reasoning:"Hand clumsiness, gait disturbance, hyperreflexia, bilateral symptoms or other upper-motor-neuron signs require urgent medical assessment."}],management:["Document a full neurological baseline and red flags; arrange medical assessment for significant or progressive motor deficit or suspected myelopathy.","If stable and appropriate, use education, tolerable movement and an individualized exercise plan; avoid forceful techniques when serious neurological pathology is suspected.","Discuss work modifications and symptom monitoring, with a clear escalation plan."],progression:["Repeat the same motor, sensory and reflex measures alongside arm function; progression of weakness overrides routine exercise progression.","Increase driving/lifting exposure as tolerated when neurological status and function are stable."],learning:["Match neurological findings to the patient's symptom distribution.","A positive provocative test is not a stand-alone diagnosis.","Cord signs and progressive deficit change the urgency."],references:[nice("Suspected neurological conditions: recognition and referral (NG127)","https://www.nice.org.uk/guidance/ng127/chapter/Recommendations-for-adults-aged-over-16"),jn("Cervical radiculopathy nonoperative management","cervical radiculopathy clinical practice guideline physical therapy")]},
{id:"expanded-02-1",category:"Clinical Red Flags",patient:"Nadeem Akhtar, 61 · retired school principal",opening:"My hands have become clumsy over several months, and recently I feel unsteady when walking. I keep dropping buttons and keys.",scene:["Nadeem attends for what he initially calls neck stiffness. The combination of progressive hand dexterity loss and gait change is the key issue, not a sport-related complaint.","The clinician must identify possible cervical cord dysfunction and arrange prompt medical assessment instead of treating this as routine neck pain."],history:[["Have you noticed changes in walking, hand use or both?","Both. I stumble on stairs and struggle with buttons."],["Any new bladder/bowel change, rapidly worsening weakness or recent trauma?","No bladder change, but walking has gradually worsened."],["Is the problem one-sided and painful, or are both hands affected?","Both hands feel awkward, even when my neck pain is mild."]],findings:["Progressive hand clumsiness with gait disturbance.","Hyperreflexia and upper-motor-neuron signs are reported in the focused examination.","The pattern is not explained by isolated local neck pain or a single peripheral nerve lesion."],examPrompt:"Which finding cluster should trigger concern for cervical myelopathy?",examReason:"Progressive hand dysfunction, gait disturbance and upper-motor-neuron signs are concerning for spinal cord involvement. Do not delay escalation to complete routine special tests or manual therapy.",diagnosis:"Suspected degenerative cervical myelopathy — prompt urgent medical assessment",diagnosisReason:"The progressive bilateral dexterity and gait changes with upper-motor-neuron signs are a high-priority cord-compression pattern. Physiotherapy should not attempt to confirm or manage this as ordinary mechanical neck pain.",differentials:[{diagnosis:"Peripheral neuropathy",reasoning:"May cause distal sensory change but does not adequately explain a coherent upper-motor-neuron and gait pattern."},{diagnosis:"Cervical radiculopathy without myelopathy",reasoning:"Can cause arm pain or focal deficits, but gait disturbance and upper-motor-neuron signs raise concern for cord involvement."}],management:["Stop routine treatment and arrange urgent medical/spinal assessment through the appropriate local pathway; urgency increases with rapid progression.","Communicate symptom onset, bilateral hand changes, gait findings and neurological signs clearly; document the handover.","Do not perform cervical thrust manipulation or delay referral for exercise trials."],progression:["Rehabilitation planning follows specialist assessment and a clear medical plan; monitor neurological status if seen again.","Any new bladder/bowel symptoms or rapid loss of function warrants emergency escalation."],learning:["Hand clumsiness plus gait change is a red-flag cluster.","A mild pain score does not mean a mild neurological problem.","Clinical safety may require referral rather than treatment."],urgent:true,references:[nice("Suspected neurological conditions: recognition and referral (NG127)","https://www.nice.org.uk/guidance/ng127/chapter/Recommendations-for-adults-aged-over-16"),jn("Degenerative cervical myelopathy recognition and referral","degenerative cervical myelopathy guideline referral signs symptoms")]},
{id:"expanded-03-1",category:"MSK & Sports",patient:"Maha Khan, 32 · graphic designer",opening:"My neck feels sore and stiff after long computer sessions. Turning to check traffic is uncomfortable, but I have no arm tingling or weakness.",scene:["Maha's symptoms vary with sustained work positions and neck movement. There was no significant trauma or systemic illness.","This case tests ordinary mechanical neck-pain reasoning while ensuring neurological and serious-pathology screening is not skipped."],history:[["Does pain travel into the arm or come with numbness or weakness?","No, it stays around the neck and upper shoulder."],["Any fever, severe unusual headache, trauma or unexplained weight loss?","No."],["What changes the symptoms?","Long uninterrupted computer sessions aggravate it; movement breaks help."]],findings:["Cervical range is mildly restricted and reproduces familiar local pain.","Upper-limb neurological screen is unremarkable in this simulation.","Symptoms vary with posture/activity and ease with movement breaks."],examPrompt:"Which findings support a mechanical neck-pain presentation while keeping the diagnosis provisional?",examReason:"Familiar local pain with movement, activity-related variation and no objective neurological deficit supports a mechanical presentation. Continue to screen for red flags and reassess if the pattern changes.",diagnosis:"Non-specific mechanical neck pain",diagnosisReason:"The local, movement-related symptoms and reassuring neurological screen fit non-specific neck pain. No single posture or tissue can be declared the cause.",differentials:[{diagnosis:"Cervical radiculopathy",reasoning:"Would become more likely with concordant arm pain, dermatomal sensory change, myotomal weakness or reflex changes."},{diagnosis:"Serious spinal or systemic pathology",reasoning:"Trauma, fever, unexplained weight loss, cancer history, severe atypical pain or progressive neurological change requires medical assessment."}],management:["Explain that symptoms are common and often influenced by workload, sleep, stress and movement tolerance rather than one 'bad posture'.","Use graded cervical/shoulder movement and strengthening selected to goals; add frequent work breaks and practical workstation variation.","Encourage normal activity within tolerance and agree a safety-net plan."],progression:["Track turning tolerance, work duration and patient-selected function; progress exercise and uninterrupted work time gradually.","Reassess the hypothesis if symptoms spread, neurological signs appear or recovery is not following the expected course."],learning:["Avoid blaming one posture as the sole cause.","Education, activity and progressive exercise should be individualized.","A reassuring initial screen is not permission to ignore new symptoms."],references:[jn("Neck pain clinical practice guideline exercise education","neck pain clinical practice guideline revision 2017 physical therapy"),nice("Suspected neurological conditions: recognition and referral (NG127)","https://www.nice.org.uk/guidance/ng127/chapter/Recommendations-for-adults-aged-over-16")]},
{id:"expanded-04-1",category:"MSK & Sports",patient:"Farah Iqbal, 38 · secondary-school teacher",opening:"A one-sided headache begins near the upper neck and gets worse when I turn my head or stay in one position too long.",scene:["Farah has recurrent unilateral headache associated with neck discomfort. A headache presentation must first be screened for red flags; neck tenderness alone cannot establish a cervicogenic source.","The assessment differentiates a possible cervical contribution from migraine and other primary or secondary headache disorders."],history:[["Was the headache sudden and maximal at onset, or associated with fever, confusion, weakness or vision loss?","No sudden onset, fever, confusion or new weakness."],["Does neck movement reproduce the familiar headache?","Turning to the right can reproduce the same pain."],["Any nausea, light sensitivity, aura or previous migraine pattern?","I sometimes dislike bright light, so I am not sure it is only from my neck."]],findings:["Restricted cervical movement with reproduction of familiar headache in the simulated examination.","Headache features overlap with primary headache disorders; no single neck test establishes the diagnosis.","Urgent headache red flags must be screened and referred when present."],examPrompt:"Why is reproduction with neck movement insufficient by itself to label a headache cervicogenic?",examReason:"Cervical musculoskeletal findings can coexist with migraine and other headache disorders. Diagnosis requires the broader headache history and appropriate medical criteria; sudden severe or neurological presentations need urgent assessment.",diagnosis:"Possible cervicogenic contribution to recurrent headache; primary headache disorder remains in the differential",diagnosisReason:"The neck-related provocation suggests a cervical contribution, but light sensitivity and incomplete headache characterization prevent a confident single-source diagnosis.",differentials:[{diagnosis:"Migraine",reasoning:"Assess episode duration, nausea, light/sound sensitivity, activity aggravation and prior stereotyped attacks."},{diagnosis:"Secondary headache requiring urgent assessment",reasoning:"Thunderclap onset, new focal neurological deficit, fever/meningism, altered consciousness or other high-risk features require urgent referral."}],management:["Complete a structured headache history and red-flag screen; refer medically when the pattern is new, atypical or concerning.","If a cervical contribution is clinically supported and safety is established, use graded neck/shoulder exercise and movement-based care matched to findings.","Avoid claiming that a tender muscle or one positive test explains every headache."],progression:["Track headache frequency, intensity, disability and neck-related triggers; coordinate with medical care if migraine or another disorder is suspected.","Reassess immediately if headache character changes or neurological/systemic warning signs appear."],learning:["Headache diagnosis requires headache-specific reasoning.","Neck findings may be contributory rather than exclusive.","Red-flag screening comes before manual treatment."],references:[jn("Cervicogenic headache diagnostic criteria and physical therapy","cervicogenic headache clinical practice guideline diagnostic criteria"),nice("Headaches in over 12s: diagnosis and management (CG150)","https://www.nice.org.uk/guidance/cg150/chapter/recommendations")]},
{id:"expanded-05-1",category:"Clinical Red Flags",patient:"Owais Ahmed, 29 · electrician",opening:"When I work with my arm overhead, it becomes heavy and tingles; sometimes my hand looks unusually pale and feels cold.",scene:["Owais is referred for shoulder discomfort, but positional sensory symptoms with visible colour/temperature change raise a neurovascular concern.","Thoracic outlet syndrome is not diagnosed by one provocative manoeuvre; vascular compromise requires timely medical assessment."],history:[["Does the arm change colour or temperature, or swell?","It sometimes looks pale and feels colder when overhead."],["Any sudden severe pain, persistent weakness or symptoms at rest?","It settles when I lower the arm, but the episodes are becoming more frequent."],["Any chest pain, breathlessness or sudden sustained limb change?","No chest pain or breathlessness today."]],findings:["Overhead position is associated with arm heaviness and paresthesia.","Reported pallor and coldness are vascular warning features and require direct assessment rather than provocative testing alone.","Document pulses, capillary refill, colour, temperature and symptom recovery without prolonged symptom provocation."],examPrompt:"What is the safe response to positional arm symptoms with pallor and coldness?",examReason:"Possible vascular compromise should not be dismissed as ordinary postural pain. Do not repeatedly provoke symptoms to 'confirm' thoracic outlet syndrome; arrange timely medical assessment, urgently if vascular changes persist or worsen.",diagnosis:"Suspected positional neurovascular compression; thoracic outlet pathology is a differential, not confirmed",diagnosisReason:"The symptom pattern requires medical evaluation because vascular compromise cannot be safely ruled out by a physiotherapy special test.",differentials:[{diagnosis:"Cervical radiculopathy",reasoning:"Can cause arm pain/paresthesia but does not explain pallor and coldness well; compare neurological findings."},{diagnosis:"Peripheral arterial or venous pathology",reasoning:"Persistent colour/temperature change, swelling, severe pain or altered pulses requires urgent medical evaluation."}],management:["Stop repeated overhead provocation and arrange prompt medical/neurovascular assessment; use emergency services for persistent acute ischemic signs or rapid deterioration.","Document positional triggers, colour/temperature changes, pulse/perfusion observations and symptom duration.","Defer routine strengthening or manual treatment until vascular risk has been assessed."],progression:["Resume rehabilitation only with an appropriate medical plan and clear activity precautions.","Escalate immediately if colour/temperature change persists, swelling develops or severe pain/weakness appears."],learning:["A 'thoracic outlet' label must not hide vascular red flags.","Provocative tests have limited diagnostic accuracy in isolation.","Safety and referral take priority over reproducing symptoms."],urgent:true,references:[jn("Thoracic outlet syndrome diagnosis vascular red flags","thoracic outlet syndrome vascular assessment clinical guideline"),nice("Suspected neurological conditions: recognition and referral (NG127)","https://www.nice.org.uk/guidance/ng127/chapter/Recommendations-for-adults-aged-over-16")]},
{id:"expanded-06-1",category:"MSK & Sports",patient:"Shahbaz Ali, 47 · taxi driver",opening:"My lower-back pain shoots down the outside of my leg to the foot, and coughing sometimes makes the leg pain sharper.",scene:["Shahbaz's symptoms extend below the knee. The clinical task is to determine whether there is nerve-root involvement, screen for cauda-equina symptoms and document neurological severity.","A radiating pain pattern alone does not prove radiculopathy; objective findings and trajectory matter."],history:[["Any new bladder/bowel change, saddle numbness or rapidly worsening leg weakness?","No, none of those."],["Where does the pain travel, and is there numbness?","Down the lateral leg toward the foot, with occasional tingling."],["Any weakness or change in walking?","My foot feels tired, but I can walk; it needs examination."]],findings:["Pain radiates below the knee with a plausible nerve-root distribution.","Examine dermatomes, myotomes, reflexes, neural sensitivity and gait; do not invent a deficit before testing.","No cauda-equina warning symptoms are reported at this encounter; safety-net explicitly."],examPrompt:"Which findings help distinguish radicular pain from radiculopathy?",examReason:"Radicular pain can occur without measurable deficit; radiculopathy implies nerve-root dysfunction supported by motor, sensory and/or reflex changes. New bladder/saddle symptoms or progressive deficit require urgent escalation.",diagnosis:"Suspected lumbar radicular pain; confirm whether objective radiculopathy is present",diagnosisReason:"The below-knee distribution and cough-related aggravation raise suspicion, but the neurological examination is needed before claiming a specific nerve-root deficit.",differentials:[{diagnosis:"Referred non-specific low-back pain",reasoning:"May refer into the buttock or thigh but usually lacks a coherent neurological deficit pattern."},{diagnosis:"Cauda equina syndrome",reasoning:"New urinary retention/incontinence, saddle sensory change, bowel/sexual dysfunction or progressive bilateral neurological deficit is an emergency pattern."}],management:["Perform and document a focused neurological screen and red-flag history; escalate promptly if significant or progressive deficit is found.","If stable, support tolerable activity and an individualized exercise/education plan; avoid treatment based on imaging labels alone.","Give clear instructions to seek urgent help for new bladder/bowel or saddle symptoms, progressive weakness or bilateral deterioration."],progression:["Repeat the same neurological measures and track walking, sleep and work tolerance.","Refer for medical reassessment if pain/deficit deteriorates or expected improvement does not occur."],learning:["Radiating pain is not identical to objective radiculopathy.","Safety-netting is part of the management plan.","The neurological examination must be documented, not assumed."],references:[nice("Low back pain and sciatica in over 16s (NG59)","https://www.nice.org.uk/guidance/ng59/chapter/recommendations","Updated 2020"),nice("Suspected neurological conditions: recognition and referral (NG127)","https://www.nice.org.uk/guidance/ng127/chapter/Recommendations-for-adults-aged-over-16")]},
{id:"expanded-08-1",category:"MSK & Sports",patient:"Abdul Sattar, 68 · retired teacher",opening:"After walking for a few minutes, both legs feel heavy. Sitting down or leaning forward over a shopping trolley helps.",scene:["Abdul has gradually reduced community walking because symptoms recur at a similar distance. Age alone does not establish spinal stenosis; vascular and other causes must be considered.","The assessment compares symptom behaviour with posture, walking capacity, neurological findings and vascular risk."],history:[["Does standing still relieve symptoms, or do you need to sit or bend forward?","Sitting or bending forward helps more than simply standing."],["Any foot wounds, colour change, cold feet or vascular history?","No wounds, but I smoke and have diabetes."],["Any new bladder/bowel symptoms or progressive weakness?","No new bladder symptoms or sudden weakness."]],findings:["Bilateral leg heaviness is provoked by walking and relieved by sitting/flexion.","Walking tolerance is reduced; assess neurological status, pulses and vascular risk rather than assuming one cause.","The symptom pattern is compatible with neurogenic claudication but not diagnostic by itself."],examPrompt:"How would you differentiate neurogenic from vascular claudication?",examReason:"Flexion relief and posture-dependent symptoms support neurogenic claudication, whereas vascular symptoms often relate to exertional demand and perfusion. Both may coexist; examine and refer when vascular disease is suspected.",diagnosis:"Suspected lumbar spinal stenosis with neurogenic claudication; vascular contribution must be assessed",diagnosisReason:"The walking-provoked symptoms relieved by sitting/flexion are suggestive, but diabetes and smoking increase vascular risk. Avoid attributing all walking limitation to the spine without a vascular screen.",differentials:[{diagnosis:"Peripheral arterial disease",reasoning:"Assess pulses, skin/perfusion findings, vascular risk and exertional pattern; suspected disease requires medical evaluation."},{diagnosis:"Peripheral neuropathy",reasoning:"May cause sensory imbalance or distal symptoms, often with a different relation to posture and walking distance."}],management:["Assess neurological function and peripheral circulation; refer for medical/vascular review when findings or risk profile warrant it.","If medically appropriate, use individualized walking/cycling or flexion-tolerant conditioning and lower-limb strengthening based on goals.","Provide urgent safety-net advice for new saddle/bladder symptoms or rapidly progressive weakness."],progression:["Track walking distance, recovery time, leg symptoms and objective neurological/vascular findings.","Progress conditioning only after safety concerns are addressed; revisit the differential if symptom behaviour changes."],learning:["Posture-related relief supports but does not prove spinal stenosis.","Vascular and neurogenic claudication can coexist.","Functional walking capacity is an important outcome."],references:[nice("Low back pain and sciatica in over 16s (NG59)","https://www.nice.org.uk/guidance/ng59/chapter/recommendations"),jn("Lumbar spinal stenosis neurogenic claudication assessment","lumbar spinal stenosis neurogenic claudication diagnosis guideline")]},
{id:"expanded-10-1",category:"Clinical Red Flags",patient:"Shamim Bibi, 74 · retired homemaker",opening:"I developed severe back pain after a small stumble. I have osteoporosis and the pain is sharply focused over the spine.",scene:["Shamim has known osteoporosis and reports pain after low-energy trauma. The profile is deliberately an older adult with fragility risk, not a young recreational athlete.","The clinician must consider vertebral fracture and arrange appropriate medical assessment rather than loading or mobilizing through suspected fracture."],history:[["Was there a fall or minor trauma, and can you move normally?","I stumbled yesterday; now rolling in bed and standing hurt sharply."],["Any previous fragility fracture, steroid use or known osteoporosis?","I have osteoporosis and a previous wrist fracture."],["Any leg weakness, saddle numbness or bladder/bowel change?","No, but the pain is much worse than my usual back ache."]],findings:["Acute focal spinal pain after low-energy trauma in a person with osteoporosis.","Focal bony tenderness and marked movement pain are reported.","Neurological and cauda-equina symptoms must be screened, but their absence does not exclude fracture."],examPrompt:"What should happen before manual therapy or exercise progression?",examReason:"Low-energy trauma plus osteoporosis and focal severe spinal pain raises concern for fragility fracture. Stop provocative loading and arrange prompt medical assessment/imaging according to local pathways.",diagnosis:"Suspected osteoporotic vertebral fracture — medical assessment required",diagnosisReason:"The risk profile and acute focal pain warrant exclusion of fracture. A physiotherapy examination cannot safely rule it out based only on movement response.",differentials:[{diagnosis:"Acute mechanical muscle strain",reasoning:"Can follow movement but is less reassuring when an older person with osteoporosis develops severe focal pain after minor trauma."},{diagnosis:"Other serious spinal pathology",reasoning:"Cancer history, systemic symptoms or neurological deterioration require further urgent assessment."}],management:["Stop routine manual therapy, spinal loading and repeated provocative testing; arrange prompt medical assessment and imaging as indicated.","Document mechanism, osteoporosis/fracture history, focal pain and neurological screen; use emergency escalation for neurological compromise.","Rehabilitation and fracture-safe movement advice follow medical confirmation and individualized precautions."],progression:["After medical clearance, coordinate graded mobility, strength, balance and osteoporosis-related falls prevention within fracture-specific precautions.","Reassess pain, transfers and walking safety; do not assume an outcome before follow-up."],learning:["Fragility risk changes the threshold for imaging/referral.","Absence of neurological signs does not rule out vertebral fracture.","Do not treat a suspected fracture as routine mechanical back pain."],urgent:true,references:[nice("Osteoporosis: assessing the risk of fragility fracture (CG146)","https://www.nice.org.uk/guidance/cg146/chapter/recommendations"),jn("Osteoporotic vertebral fracture clinical assessment","osteoporotic vertebral fracture clinical practice guideline assessment imaging")]},
{id:"expanded-13-1",category:"MSK & Sports",patient:"Khalid Mahmood, 66 · retired mechanic",opening:"My shoulder aches deep inside and has become stiff over the last year. It grinds a little and reaching a shelf is difficult.",scene:["Khalid's symptoms are gradual and affect daily reach. The clinician should distinguish degenerative glenohumeral joint symptoms from adhesive capsulitis and cuff-related pain.","Do not infer osteoarthritis from age alone; consider pattern, function, trauma and whether imaging would change management."],history:[["Was the onset sudden or gradual?","Gradual, over about a year."],["Is the pain deep in the joint, and is there stiffness or crepitus?","Yes, deep ache and grinding; both reaching and rotation are limited."],["Any fever, unexplained weight loss or recent major trauma?","No."]],findings:["Both active and passive shoulder range are restricted.","Crepitus and deep joint-related pain are reported.","Assess cervical contribution, strength within available range and functional limitations."],examPrompt:"Which pattern makes glenohumeral osteoarthritis a reasonable working hypothesis?",examReason:"Gradual deep shoulder pain, crepitus and restricted active/passive range may fit glenohumeral osteoarthritis, but adhesive capsulitis and other causes can overlap. Confirm the clinical picture and refer for medical assessment when needed.",diagnosis:"Probable glenohumeral osteoarthritis",diagnosisReason:"The gradual deep ache, crepitus and global restriction are compatible with degenerative joint disease; diagnosis remains provisional without full assessment.",differentials:[{diagnosis:"Adhesive capsulitis",reasoning:"Often has marked external-rotation restriction and a painful/stiff phase pattern; clinical overlap is possible."},{diagnosis:"Rotator-cuff-related shoulder pain",reasoning:"Often shows pain with active/resisted loading and relatively better passive range unless stiffness coexists."}],management:["Agree functional priorities and explain the likely degenerative/stiffness pattern without implying inevitable decline.","Use tailored range, strengthening and task practice within tolerance; consider medical review for diagnostic uncertainty or persistent severe limitation.","Discuss pacing and adaptation of overhead tasks while maintaining useful activity."],progression:["Track dressing, shelf reach, pain and range; progress strength and daily tasks according to response.","Reassess if sudden deterioration, trauma, systemic features or a new neurological pattern appears."],learning:["Age is not a diagnosis.","Compare active and passive range and consider overlapping conditions.","Treatment should target function and capacity, not promise structural reversal."],references:[nice("Osteoarthritis in over 16s: diagnosis and management (NG226)","https://www.nice.org.uk/guidance/ng226/chapter/Recommendations"),jn("Glenohumeral osteoarthritis exercise management","glenohumeral osteoarthritis clinical practice guideline exercise physical therapy")]},
{id:"expanded-14-1",category:"MSK & Sports",patient:"Hamza Rauf, 25 · amateur rugby player",opening:"I landed directly on the point of my shoulder during a tackle. Now reaching across my chest hurts.",scene:["Hamza has focal superior shoulder pain after direct impact. Before calling it an acromioclavicular (AC) sprain, assess deformity, fracture risk and neurovascular status.","The case is about injury-specific assessment and appropriate referral, not immediate strengthening."],history:[["Where did you land and where is the pain?","Directly onto the shoulder; the pain is at the top, near the collarbone."],["Any deformity, skin tenting, numbness or hand colour change?","There is a small bump and tenderness, but my hand feels normal."],["Can you move the shoulder and tolerate weight through the arm?","Lifting and crossing the arm are painful."]],findings:["Focal AC-joint tenderness and pain with cross-body adduction.","Assess clavicle/shoulder contour, skin integrity, range, neurovascular status and associated fracture/dislocation signs.","A cross-body test is supportive only when interpreted with mechanism and overall assessment."],examPrompt:"Which features require medical assessment before routine AC-joint rehabilitation?",examReason:"Visible deformity, skin compromise, severe pain, suspected fracture/dislocation or neurovascular change require prompt medical evaluation. Classification of AC injury severity should not be guessed from one test.",diagnosis:"Suspected acromioclavicular joint injury after direct impact",diagnosisReason:"The mechanism and focal superior shoulder pain fit an AC injury, but injury grade and associated fracture/dislocation need appropriate assessment.",differentials:[{diagnosis:"Clavicle fracture",reasoning:"Focal clavicular bony tenderness, deformity or pain throughout the clavicle warrants medical assessment/imaging."},{diagnosis:"Rotator cuff injury",reasoning:"More likely with marked weakness or pain with cuff loading, particularly if the mechanism and examination support it."}],management:["Arrange medical assessment/imaging when fracture, significant displacement or neurovascular/skin concerns are present.","For a medically cleared stable injury, use symptom-guided support and early tolerable movement, then restore strength and functional loading.","Avoid contact sport until pain, range, strength and sport-specific demands are safely met."],progression:["Reassess pain, range, strength and cross-body/overhead tasks; progress contact exposure only after clinical clearance when required.","Escalate if pain, deformity, skin changes or neurological symptoms worsen."],learning:["Mechanism and focal anatomy help narrow the diagnosis.","Do not grade an AC injury from one provocative test.","Screen for fracture and neurovascular compromise first."],references:[jn("Acromioclavicular joint injury diagnosis and rehabilitation","acromioclavicular joint injury clinical guideline rehabilitation"),aaos("Shoulder injuries and fractures","https://orthoinfo.aaos.org/en/diseases--conditions/shoulder-separation/")]},
{id:"expanded-15-1",category:"MSK & Sports",patient:"Zubair Khan, 23 · recreational swimmer",opening:"My shoulder sometimes feels as if it will slip out when I reach back or put my arm overhead.",scene:["Zubair reports repeated apprehension in vulnerable positions rather than progressive stiffness. Clarify whether there has been a documented dislocation and screen for associated injury.","The assessment should distinguish instability from pain-only presentations and avoid repeatedly forcing the shoulder into a provocative position."],history:[["Has the shoulder ever visibly dislocated or needed reduction?","It slipped out once during a game and was reduced in hospital."],["Which positions provoke apprehension?","Arm out to the side and rotated backward."],["Any new numbness, cold hand or acute loss of movement?","No current numbness or colour change."]],findings:["Apprehension in a vulnerable abducted/external-rotation position.","History of a prior dislocation supports instability; assess range, strength, control and neurovascular status.","Avoid aggressive provocative testing if apprehension is marked or instability risk is high."],examPrompt:"Why is apprehension different from pain during a shoulder test?",examReason:"A sense of impending displacement in the relevant position is more suggestive of instability than pain alone. Interpret the response with history and control; stop testing if unsafe.",diagnosis:"Recurrent glenohumeral instability, likely anterior pattern pending full assessment",diagnosisReason:"Prior dislocation plus positional apprehension suggests instability. Exact direction, associated labral/bony injury and recurrence risk require clinical assessment and medical input as indicated.",differentials:[{diagnosis:"Rotator-cuff-related shoulder pain",reasoning:"Pain with resisted cuff loading and preserved stability may explain symptoms without a true slipping/apprehension history."},{diagnosis:"Labral or bony injury associated with dislocation",reasoning:"Recurrent episodes, traumatic mechanism or persistent dysfunction may warrant specialist assessment/imaging."}],management:["Avoid repeatedly provoking the unstable position; explain temporary activity modifications without unnecessary long-term immobilization.","Use progressive rotator-cuff and scapular control work, then graded exposure to sport-specific positions when clinically appropriate.","Refer for specialist/medical review for recurrent dislocations, major functional limitation, suspected structural injury or neurovascular symptoms."],progression:["Track episodes, apprehension, strength, range and task-specific control; increase overhead/sport exposure progressively.","Reassess after any new subluxation/dislocation or new neurological symptoms."],learning:["A slipping/apprehension history changes the shoulder differential.","Testing should not intentionally destabilize the joint.","Rehabilitation progresses from control to task-specific exposure."],references:[jn("Shoulder instability clinical practice guideline rehabilitation","shoulder instability clinical practice guideline rehabilitation return to sport"),aaos("Shoulder dislocation and instability","https://orthoinfo.aaos.org/en/diseases--conditions/shoulder-dislocation/")]},
{id:"expanded-16-1",category:"MSK & Sports",patient:"Farhan Qureshi, 38 · carpenter",opening:"Gripping tools and lifting a kettle make the outside of my elbow hurt, especially after a long workday.",scene:["Farhan's symptoms are load-related and localized around the lateral elbow. The assessment should test functional grip and tendon loading while screening for nerve or joint causes.","A provocative test is one part of the assessment; no single manoeuvre proves tendinopathy."],history:[["What work or activity increases symptoms?","Sustained gripping, hammering and lifting with the palm down."],["Any neck pain, tingling or numbness?","No tingling; the pain stays around the outer elbow."],["Any sudden injury, locking or marked loss of movement?","No, it built up gradually."]],findings:["Focal lateral epicondyle tenderness with familiar pain on resisted wrist extension/grip.","Grip-related function is limited; assess wrist/elbow range and neurological signs if indicated.","No acute trauma or neurological symptoms are reported."],examPrompt:"What supports lateral elbow tendinopathy and what alternatives still need screening?",examReason:"Localized load-related pain and concordant resisted wrist-extensor loading support lateral elbow tendinopathy. Consider radial tunnel or cervical referral when symptoms or neurological findings do not fit.",diagnosis:"Lateral elbow tendinopathy (lateral epicondylalgia)",diagnosisReason:"The gradual onset, gripping intolerance and focal lateral tenderness with resisted loading fit a tendon-related presentation.",differentials:[{diagnosis:"Radial tunnel syndrome",reasoning:"Pain may be more distal and may not map neatly to focal epicondylar tenderness; assess nerve-related findings."},{diagnosis:"Cervical referral",reasoning:"Neck symptoms or concordant neurological findings suggest a proximal contributor."}],management:["Explain load-related tendon pain and temporarily adjust the most provocative gripping volume rather than stopping all activity.","Use progressive wrist-extensor and grip loading, beginning at a tolerable level and advancing based on response.","Consider work-tool grip/handle and task rotation changes; refer if atypical, traumatic or persistently worsening."],progression:["Track grip tolerance, pain during work and a repeatable functional task; increase work exposure in steps.","If the pattern fails to improve, revisit diagnosis and adherence/load rather than simply adding passive modalities."],learning:["A tendon-related diagnosis should fit both history and load testing.","Progressive loading and activity modification are central.","Consider nerve and cervical sources when the pattern is atypical."],references:[jn("Lateral elbow tendinopathy rehabilitation guideline","lateral elbow pain clinical practice guideline physical therapy exercise"),aaos("Tennis elbow","https://orthoinfo.aaos.org/en/diseases--conditions/tennis-elbow-lateral-epicondylitis/")]},
{id:"expanded-17-1",category:"MSK & Sports",patient:"Muneeb Shah, 43 · electrician",opening:"Pain on the inner side of my elbow flares when I grip tools, lift a bag or bend my wrist against resistance.",scene:["Muneeb's symptoms are localized medially and linked to wrist-flexor/pronator loading. Ulnar nerve symptoms and medial ligament injury remain alternatives depending on the full history.","Avoid assuming all medial elbow pain is tendinopathy, especially in throwing athletes or people with paresthesia."],history:[["Any tingling in the ring and little fingers?","No tingling or hand weakness."],["What loading reproduces the familiar pain?","Gripping and resisted wrist flexion, especially after repeated work."],["Was there a sudden valgus injury or throwing-related pop?","No, it built up gradually at work."]],findings:["Medial epicondylar tenderness with pain on resisted wrist flexion/pronation.","Ulnar nerve sensory symptoms are not reported; screen sensation and nerve irritability if indicated.","Assess elbow stability and range when mechanism or activity raises concern."],examPrompt:"Which findings support medial epicondylalgia over cubital tunnel or ligament injury?",examReason:"Gradual medial pain tied to wrist-flexor/pronator loading supports tendinopathy. Ring/little-finger paresthesia or valgus instability changes the differential.",diagnosis:"Medial elbow tendinopathy (medial epicondylalgia)",diagnosisReason:"The gradual work-related onset and concordant tendon-loading pain fit medial epicondylalgia, without reported ulnar sensory symptoms or acute valgus trauma.",differentials:[{diagnosis:"Cubital tunnel syndrome",reasoning:"Tingling in the ring/little fingers, symptoms with elbow flexion or intrinsic hand weakness suggest ulnar neuropathy."},{diagnosis:"Ulnar collateral ligament injury",reasoning:"Throwing-related pain, acute valgus force or instability requires a different assessment and possible specialist review."}],management:["Modify repeated high-force gripping and wrist-flexion/pronation volume while preserving tolerable activity.","Use graded wrist-flexor/pronator and grip strengthening based on symptom response.","Refer if there is instability, significant weakness, neurological deficit or a traumatic onset."],progression:["Reassess grip and work-task tolerance and gradually restore sustained tool use.","If nerve symptoms or instability appear, pause the tendon-only plan and reassess."],learning:["Medial elbow pain has tendon, nerve and ligament differentials.","Mechanism and neurological symptoms matter.","Progress loading against real work demands."],references:[jn("Medial elbow tendinopathy conservative rehabilitation","medial epicondylitis physical therapy exercise evidence"),aaos("Elbow conditions","https://orthoinfo.aaos.org/en/diseases--conditions/")]},
{id:"expanded-18-1",category:"MSK & Sports",patient:"Bilal Riaz, 36 · call-centre team lead",opening:"My ring and little fingers tingle after I keep my elbow bent while using the phone or sleeping.",scene:["Bilal's symptoms follow the ulnar side of the hand and are position-sensitive. The assessment should identify persistent motor/sensory deficit and consider cervical or more proximal nerve causes.","Do not diagnose cubital tunnel syndrome solely from a tingling description; examine nerve distribution and function."],history:[["Which fingers tingle?","The little finger and the little-finger side of the ring finger."],["What positions trigger it?","Holding the phone with my elbow bent and sleeping with it tucked under me."],["Any hand clumsiness, constant numbness or neck symptoms?","Occasionally I fumble small objects; no neck pain."]],findings:["Ulnar-distribution paresthesia with symptoms aggravated by sustained elbow flexion.","Assess intrinsic hand strength, sensation, muscle bulk and whether symptoms are persistent or progressive.","Compare cervical screen and other possible ulnar nerve compression sites when indicated."],examPrompt:"Which pattern supports ulnar neuropathy at the elbow and raises concern for severity?",examReason:"Position-related ulnar-distribution symptoms support cubital tunnel involvement; persistent numbness, intrinsic weakness or wasting suggests more significant neuropathy and warrants medical assessment.",diagnosis:"Suspected cubital tunnel syndrome (ulnar neuropathy at the elbow)",diagnosisReason:"The finger distribution and elbow-flexion provocation fit ulnar nerve irritation near the elbow, but objective deficits and proximal causes must be assessed.",differentials:[{diagnosis:"C8/T1 cervical radiculopathy",reasoning:"Neck-related symptoms or deficits beyond the ulnar territory may indicate a nerve-root source."},{diagnosis:"Ulnar neuropathy at the wrist",reasoning:"Distribution and motor findings differ by lesion site; examine dorsal ulnar sensation and intrinsic muscle pattern."}],management:["Reduce prolonged elbow flexion and direct pressure over the cubital tunnel; consider a comfortable night-position strategy if appropriate.","Monitor hand strength and sensation; arrange medical assessment for persistent deficit, weakness, muscle wasting or progression.","Use nerve-related advice cautiously and avoid forceful nerve tensioning that worsens symptoms."],progression:["Track night symptoms, dexterity, sensation and intrinsic strength; review the response to position changes.","Escalate if weakness, constant numbness or muscle wasting develops."],learning:["Map ulnar symptoms and assess lesion severity.","Avoid pressure and sustained elbow flexion when provocative.","Progressive motor deficit warrants referral."],references:[jn("Cubital tunnel syndrome conservative treatment guideline","cubital tunnel syndrome conservative management ulnar neuropathy elbow guideline"),aaos("Cubital tunnel syndrome","https://orthoinfo.aaos.org/en/diseases--conditions/cubital-tunnel-syndrome/")]},
{id:"expanded-20-1",category:"MSK & Sports",patient:"Fatima Zahra, 34 · mother of a toddler",opening:"The thumb side of my wrist hurts when I lift my child, wring a cloth or grip a heavy pan.",scene:["Fatima has gradual radial wrist pain during repeated lifting. Assess local tendon loading, thumb-base joint symptoms and sensory change before selecting treatment.","The Finkelstein/Eichhoff family of tests can be painful in several conditions and should not be used in isolation."],history:[["Where is the pain most localized?","Near the radial styloid, at the thumb side of my wrist."],["What tasks reproduce it?","Lifting my child under the arms and gripping pans."],["Any numbness, trauma or pain centered at the thumb-base joint?","No numbness or injury; it is most tender just above the wrist crease."]],findings:["Radial styloid tenderness and familiar pain with thumb tendon loading.","Assess thumb/wrist function and compare with first carpometacarpal joint symptoms.","No sensory deficit is reported in this presentation."],examPrompt:"What helps distinguish de Quervain tenosynovitis from thumb-base osteoarthritis?",examReason:"Radial styloid tendon-region pain with thumb tendon loading supports de Quervain tenosynovitis; basal joint pain with pinch and local CMC tenderness suggests another source. Avoid overinterpreting a single provocative test.",diagnosis:"Probable de Quervain tenosynovitis",diagnosisReason:"The focal radial-styloid pain and child-lifting aggravation fit first dorsal compartment tendon irritation.",differentials:[{diagnosis:"Thumb carpometacarpal osteoarthritis",reasoning:"Pain is more centered at the thumb base and reproduced by pinch/jar opening, especially with joint tenderness."},{diagnosis:"Superficial radial nerve irritation",reasoning:"Burning/tingling or altered sensation over the dorsoradial hand suggests a nerve contribution."}],management:["Temporarily adapt lifting grips and reduce repeated painful thumb abduction/extension while keeping the hand active.","Consider short-term thumb-spica support if suitable and progress tendon/functional loading as symptoms settle.","Refer for medical review if diagnosis is uncertain, symptoms are severe/persistent or neurological/systemic features appear."],progression:["Track child-lifting tolerance, grip and pain with daily tasks; reintroduce loads gradually.","Reassess if pain localizes to the CMC joint or sensory symptoms emerge."],learning:["Location within the radial wrist matters.","Provocative tests need interpretation alongside history and palpation.","Modify task load while preserving function."],references:[jn("De Quervain tenosynovitis clinical management","de quervain tenosynovitis clinical practice guideline treatment"),aaos("De Quervain's tenosynovitis","https://orthoinfo.aaos.org/en/diseases--conditions/de-quervains-tendinosis/")]},
{id:"expanded-21-1",category:"MSK & Sports",patient:"Nusrat Javed, 63 · home-based tailor",opening:"The base of my thumb hurts when I open jars, turn keys or pinch fabric clips.",scene:["Nusrat has thumb-base pain during pinch and grip tasks, with no acute injury. This differs from radial-styloid tendon pain even though both can be described as thumb-side wrist pain.","Assess function and joint tenderness, and avoid painful repeated testing when the pattern is already clear."],history:[["Where is the most painful point?","At the base of the thumb near the wrist, not up along the tendon."],["Which tasks are hardest?","Opening jars, turning keys and pinching fabric."],["Any numbness, redness, warmth or sudden swelling?","No numbness or sudden swelling."]],findings:["Focal first carpometacarpal joint tenderness with pain during pinch loading.","Grip/pinch function is limited; assess range, stability and adjacent tendon/nerve symptoms.","No acute inflammatory or traumatic presentation is described."],examPrompt:"Which finding pattern supports thumb CMC osteoarthritis?",examReason:"Thumb-base pain during pinch and local CMC tenderness support first CMC osteoarthritis; imaging is not always necessary for a typical presentation but may be considered when diagnosis is uncertain or management changes.",diagnosis:"Probable first carpometacarpal osteoarthritis",diagnosisReason:"The pain location and pinch-related limitation fit thumb-base osteoarthritis better than radial-styloid tendon disease.",differentials:[{diagnosis:"De Quervain tenosynovitis",reasoning:"Usually more focal at the radial styloid and provoked by first dorsal compartment tendon loading."},{diagnosis:"Inflammatory arthritis",reasoning:"Multiple swollen/warm joints, prolonged morning stiffness or systemic features warrant medical assessment."}],management:["Discuss joint load strategies and consider a thumb-base orthosis for tasks if appropriate and acceptable.","Use tailored thumb/hand strengthening and task adaptation, balancing support with continued useful activity.","Refer for medical review if symptoms are atypical, inflammatory features appear or function remains severely limited."],progression:["Track jar opening, key turning and pinch tolerance; adjust orthosis or exercise according to real-world response.","Reassess if symptoms spread to multiple joints or inflammatory signs develop."],learning:["Thumb CMC and radial-styloid pain are not interchangeable.","Treatment should target meaningful pinch and grip tasks.","Joint support is an option, not a universal requirement."],references:[nice("Osteoarthritis in over 16s: diagnosis and management (NG226)","https://www.nice.org.uk/guidance/ng226/chapter/Recommendations"),jn("Thumb carpometacarpal osteoarthritis hand therapy","thumb carpometacarpal osteoarthritis hand therapy orthosis exercise evidence")]},
{id:"expanded-22-1",category:"MSK & Sports",patient:"Nasreen Akhtar, 57 · primary-school teacher",opening:"I feel a deep ache in my groin and stiffness after sitting. Putting on socks and getting out of a low chair are harder now.",scene:["Nasreen's symptoms are gradual and affect hip flexion and rotation tasks. The clinician should assess hip range and function while screening for fracture, inflammatory or referred causes.","Do not diagnose hip osteoarthritis from age alone or assume all hip pain is intra-articular."],history:[["Where is the pain strongest?","Deep in the groin and sometimes the front of the thigh."],["What activities are limited?","Stairs, socks and standing after sitting."],["Any trauma, fever, rapid deterioration or inability to bear weight?","No trauma or fever; it has slowly worsened."]],findings:["Hip internal rotation and flexion are restricted and reproduce familiar groin pain.","Weight-bearing and chair-rise tasks are painful.","Screen lumbar contribution and red flags; the pattern is not based on one special test."],examPrompt:"Which combination supports hip osteoarthritis as a working diagnosis?",examReason:"Gradual groin pain, stiffness, restricted internal rotation and functional weight-bearing difficulty are compatible with hip OA. Consider referred lumbar pain and other joint pathology if findings do not fit.",diagnosis:"Probable symptomatic hip osteoarthritis",diagnosisReason:"The symptom location, gradual course and restricted painful hip movement fit hip OA, but the diagnosis remains clinical and must be revisited if atypical features appear.",differentials:[{diagnosis:"Lumbar referred pain",reasoning:"Spinal movement and neurological findings may reproduce or explain symptoms beyond the hip joint."},{diagnosis:"Femoral neck fracture or other serious pathology",reasoning:"Acute severe pain, trauma, inability to bear weight or systemic risk requires urgent medical assessment."}],management:["Explain the condition and agree goals such as socks, chair rise and stairs; avoid unnecessary activity avoidance.","Use progressive strengthening and aerobic activity within tolerance, plus practical task adaptation and weight-management support when relevant and wanted.","Refer for medical review when diagnosis is uncertain, symptoms change rapidly or function is severely affected despite appropriate care."],progression:["Repeat a functional measure such as chair rise or walking tolerance alongside pain and range.","Progress activity gradually; reassess if groin pain becomes acute or weight bearing suddenly fails."],learning:["Hip OA is a clinical pattern, not simply an X-ray label.","Exercise and functional goals are core management elements.","Red flags and lumbar contributors still matter."],references:[nice("Osteoarthritis in over 16s: diagnosis and management (NG226)","https://www.nice.org.uk/guidance/ng226/chapter/Recommendations"),jn("Hip osteoarthritis physiotherapy exercise guideline","hip osteoarthritis clinical practice guideline exercise physical therapy")]},
{id:"expanded-24-1",category:"MSK & Sports",patient:"Ammar Siddiqui, 24 · amateur martial-arts trainee",opening:"Deep squats and turning on my right leg cause a sharp ache in the groin. Walking normally is mostly comfortable.",scene:["Ammar's symptoms occur during deep hip flexion and rotation. Femoroacetabular impingement syndrome requires symptoms, clinical signs and imaging findings considered together—not a positive flexion test alone.","Screen for stress fracture, acute joint pathology and other causes of groin pain before sport loading."],history:[["Which positions reproduce the pain?","Deep squat, low kicks and pivoting with the hip bent."],["Any sudden onset, trauma, night pain or pain with ordinary walking?","It came on gradually; ordinary walking is mostly fine."],["Any catching, locking or loss of weight-bearing ability?","Occasional pinch but no locking or inability to walk."]],findings:["Concordant groin pain with hip flexion/adduction/rotation testing.","Assess range, strength, functional squat and sport demands; the test is not diagnostic in isolation.","No acute inability to bear weight is described; screen for stress injury if risk/history suggests it."],examPrompt:"Why does a positive FADIR test not prove femoroacetabular impingement syndrome?",examReason:"FADIR can reproduce pain in several hip disorders and may be positive in asymptomatic people. A syndrome requires a matching symptom pattern, clinical signs and appropriate imaging context when indicated.",diagnosis:"Possible femoroacetabular impingement syndrome; further clinical correlation required",diagnosisReason:"Deep-flexion-related groin pain and concordant provocation support the hypothesis, but neither morphology nor one test alone establishes symptomatic FAI.",differentials:[{diagnosis:"Hip flexor/adductor-related pain",reasoning:"Pain may be reproduced more specifically by resisted muscle loading and palpation."},{diagnosis:"Femoral neck stress injury",reasoning:"Progressive groin pain with impact/weight bearing, training spikes or bone-health risk warrants prompt medical assessment and avoidance of impact."}],management:["Temporarily modify deep-flexion and pivoting loads that reproduce symptoms while preserving pain-tolerable conditioning.","Use progressive hip/trunk strength and movement retraining linked to the athlete's actual tasks; do not promise that exercises alter bony morphology.","Refer for medical assessment if pain escalates, weight bearing becomes painful or stress injury is suspected."],progression:["Track squat depth, sport-specific function and symptom response; reintroduce deep flexion and pivoting in graded stages.","Reassess if symptoms become persistent at rest or the clinical picture changes."],learning:["FAI syndrome is not diagnosed by a test or imaging morphology alone.","Groin pain has important alternatives, including stress injury.","Rehabilitation targets symptoms and function."],references:[jn("Femoroacetabular impingement syndrome consensus diagnosis and management","femoroacetabular impingement syndrome Warwick agreement rehabilitation"),jn("Hip-related pain and femoral neck stress injury assessment","femoral neck stress fracture athlete groin pain clinical guideline")]},
{id:"expanded-25-1",category:"MSK & Sports",patient:"Zainab Khatoon, 67 · homemaker",opening:"My knees ache on stairs and feel stiff for a short time in the morning. I am walking less because I worry the joint is wearing out.",scene:["Zainab reports gradual activity-related knee pain and brief morning stiffness. The assessment should support activity and function while checking for inflammatory or acute red flags.","The goal is not to treat an X-ray but to build capacity around her daily tasks."],history:[["How long does morning stiffness last?","Usually around ten minutes, then it eases as I move."],["Any hot swollen joint, prolonged stiffness or sudden inability to bear weight?","No hot joint or sudden change."],["What matters most to you?","I want to use stairs and walk to the market more confidently."]],findings:["Gradual knee pain with weight-bearing and stairs.","Crepitus and reduced range may be present; interpret with history rather than as proof alone.","No acute hot swollen joint or systemic illness is described."],examPrompt:"Which clinical pattern supports knee osteoarthritis and what would change the differential?",examReason:"Activity-related pain, brief stiffness and functional limitation are compatible with OA. A hot swollen joint, prolonged inflammatory stiffness, systemic symptoms or acute weight-bearing failure needs medical evaluation.",diagnosis:"Symptomatic knee osteoarthritis is the leading working diagnosis",diagnosisReason:"The gradual load-related pain and brief morning stiffness fit a common OA presentation; examination should establish impairments and function rather than rely on crepitus alone.",differentials:[{diagnosis:"Inflammatory arthritis",reasoning:"Multiple swollen joints, prolonged morning stiffness, warmth or systemic features warrant medical assessment."},{diagnosis:"Acute septic arthritis",reasoning:"A hot, markedly painful swollen joint with fever or systemic illness is an urgent medical problem."}],management:["Explain that appropriate movement and exercise can help symptoms and function; avoid telling the patient that activity inevitably damages the joint.","Use individualized strengthening and aerobic exercise, with graded walking and stair practice; adapt starting dose to confidence and irritability.","Discuss weight-management support only where relevant and in a respectful, shared-decision manner."],progression:["Track chair rise, walking time or stair tolerance and adjust load gradually.","Seek medical review for sudden marked swelling, warmth, fever, rapid deterioration or new inability to bear weight."],learning:["Crepitus alone does not diagnose OA.","Education and exercise are core management, not optional extras.","Red flags change the plan."],references:[nice("Osteoarthritis in over 16s: diagnosis and management (NG226)","https://www.nice.org.uk/guidance/ng226/chapter/Recommendations")]},
{id:"expanded-27-1",category:"MSK & Sports",patient:"Haris Jamil, 27 · volleyball player",opening:"I have a very specific pain just below the kneecap when I jump, land or do repeated squats.",scene:["Haris increased jumping volume ahead of a tournament. Symptoms are localized to the patellar tendon and linked to high tendon load.","Differentiate tendon-related pain from patellofemoral pain, acute rupture and other knee pathology."],history:[["Where is the pain most specific?","Right at the tendon below the kneecap."],["Did it start suddenly with a snap, or gradually with increased training?","Gradually after adding more jumps."],["Can you actively straighten the knee and walk?","Yes, but repeated jumps hurt."]],findings:["Focal patellar tendon tenderness and pain with tendon-loading tasks.","Assess extensor mechanism integrity, strength and jump/landing load; acute loss of active extension requires urgent assessment.","Pain is load-related rather than diffuse around the patella in this presentation."],examPrompt:"What must be excluded before treating this as patellar tendinopathy?",examReason:"A sudden snap, major swelling or inability to actively extend the knee raises concern for extensor mechanism injury. Gradual focal tendon pain with jumping supports tendinopathy once serious injury is excluded.",diagnosis:"Patellar tendinopathy",diagnosisReason:"The gradual training-load increase, focal tendon pain and jump-related symptoms fit patellar tendinopathy; load capacity and irritability guide treatment.",differentials:[{diagnosis:"Patellofemoral pain",reasoning:"Often more diffuse peripatellar/retropatellar pain during squats, stairs and prolonged sitting."},{diagnosis:"Patellar tendon rupture",reasoning:"Acute injury, major swelling, palpable defect or inability to actively extend requires urgent medical assessment."}],management:["Temporarily reduce the most provocative jumping volume while preserving tolerable strength work and conditioning.","Use progressive quadriceps/tendon loading with an individualized pain-monitoring approach, advancing toward energy-storage and jumping tasks.","Coordinate training load so rehabilitation and team practice are not both increased sharply at once."],progression:["Track pain during loading, next-day response, strength and repeated jump/landing capacity.","Return to full jumping only after progressive energy-storage tasks and sport-specific exposure are tolerated."],learning:["Training-load changes are clinically relevant.","Tendon rehabilitation requires progressive loading and patience.","Exclude extensor mechanism rupture when the onset is acute."],references:[jn("Patellar tendinopathy rehabilitation evidence","patellar tendinopathy clinical practice guideline progressive tendon loading athlete"),jn("Patellar tendon rupture diagnosis red flags","patellar tendon rupture inability active extension guideline")]},
{id:"expanded-29-1",category:"MSK & Sports",patient:"Hassan Raza, 24 · university footballer",opening:"I twisted my knee while turning. It swelled later that day and now catches when I squat or turn.",scene:["Hassan's knee pain followed a twisting event and includes mechanical symptoms. A meniscal injury is possible, but ACL injury, fracture and a truly locked knee must be considered.","Clarify whether there is a fixed block to extension versus painful clicking or intermittent catching."],history:[["Did the knee swell rapidly, and did you hear a pop?","It swelled over several hours; I do not remember a clear pop."],["Can you fully straighten it?","It hurts near the end, but it is not stuck in one position."],["Any giving way or inability to bear weight?","It feels unreliable when turning, but I can walk."]],findings:["Joint-line tenderness and twisting-related pain.","Intermittent catching is reported; distinguish this from a true locked knee with fixed loss of extension.","Assess effusion, range, ligament stability and weight-bearing safety; do not infer a meniscal tear from one test."],examPrompt:"Which feature would change this from routine assessment to urgent referral?",examReason:"A truly locked knee, fracture concern, large acute effusion or major instability needs prompt medical/orthopaedic assessment. Meniscal provocation tests have limited accuracy in isolation.",diagnosis:"Suspected meniscal injury after knee twisting",diagnosisReason:"The mechanism, joint-line pain and catching support a meniscal differential, but the full examination is needed and ACL or other injury may coexist.",differentials:[{diagnosis:"ACL injury",reasoning:"A pivoting mechanism with rapid effusion and instability or a positive Lachman test increases suspicion."},{diagnosis:"Patellofemoral pain",reasoning:"Usually produces peripatellar load-related pain and does not typically explain a traumatic joint-line pattern with effusion."}],management:["Assess weight-bearing, effusion, range, ligament stability and whether extension is mechanically blocked; refer urgently for a true locked knee or suspected significant injury.","Avoid repeated provocative twisting while acute symptoms settle; maintain safe movement and loading within assessment findings.","Use shared decisions for imaging or orthopaedic review based on symptoms, examination and local pathways."],progression:["Reassess swelling, extension, strength and functional control; build progressive lower-limb strength and task exposure if conservative management is appropriate.","Refer if locking, recurrent effusion, instability or worsening function persists."],learning:["A meniscal label should not be based on a single test.","True locking is different from clicking or pain-limited movement.","ACL and meniscal injuries can coexist."],references:[jn("Meniscal injury diagnosis and management guideline","meniscal tear clinical practice guideline physical therapy rehabilitation"),aaos("Meniscus tears","https://orthoinfo.aaos.org/en/diseases--conditions/meniscus-tears/")]},
{id:"expanded-30-1",category:"MSK & Sports",patient:"Sadia Noor, 30 · amateur netball player",opening:"Another player hit the outside of my knee, and the inside now hurts when I turn or put weight through it.",scene:["Sadia describes a valgus force with medial knee pain. Assess for fracture, ACL/meniscal co-injury and the degree of medial instability before choosing rehabilitation.","Do not grade ligament injury from tenderness alone."],history:[["How did the force occur?","The outside of my bent knee was pushed inward during a collision."],["Did the knee swell quickly or feel unstable?","Some swelling later; it feels sore but has not fully given way."],["Can you bear weight and straighten the knee?","I can walk carefully and straighten it slowly."]],findings:["Medial knee tenderness after a valgus mechanism.","Valgus stress may be painful or lax; compare cautiously and interpret with swelling and guarding.","Assess ACL, meniscal, bony and neurovascular concerns as indicated."],examPrompt:"What combination supports an MCL sprain and what co-injuries should be checked?",examReason:"Valgus mechanism and medial tenderness/laxity support MCL injury, but associated ACL or meniscal injury can occur. Significant laxity, fracture concern or inability to bear weight warrants medical review.",diagnosis:"Suspected medial collateral ligament sprain",diagnosisReason:"The mechanism and medial findings are compatible with MCL injury; severity and associated injury require a full assessment.",differentials:[{diagnosis:"Medial meniscal injury",reasoning:"Joint-line pain with twisting, catching or locking may indicate meniscal involvement."},{diagnosis:"ACL injury",reasoning:"Pivoting trauma, rapid effusion and instability should prompt ligament assessment."}],management:["Protect from painful valgus loading and arrange medical review if marked instability, fracture concern or associated injury is suspected.","For a stable injury, progress range of motion, quadriceps/hamstring strength and balance within symptom and stability limits.","Use a brace only when clinically indicated and coordinate return-to-sport timing with injury severity."],progression:["Reassess effusion, range, stability, strength and single-leg control.","Progress running, cutting and contact only when stability and sport-specific function are adequate."],learning:["Mechanism helps direct the exam but does not determine grade.","Screen for associated injuries.","Return to sport is criterion-based, not calendar-only."],references:[jn("Medial collateral ligament injury rehabilitation","medial collateral ligament knee sprain clinical practice guideline rehabilitation"),aaos("Knee ligament injuries","https://orthoinfo.aaos.org/en/diseases--conditions/knee-ligament-injuries/")]},
{id:"expanded-32-1",category:"MSK & Sports",patient:"Rayan Malik, 22 · football winger",opening:"My ankle hurts above the joint after my foot was forced outward while planted. Turning and pushing off are painful.",scene:["Rayan describes an external-rotation mechanism and pain above the ankle, which raises concern for a syndesmotic injury rather than a routine lateral sprain.","Assess weight bearing, bony tenderness, syndesmosis and associated fracture; do not return the athlete to cutting drills based on walking alone."],history:[["Where is the pain compared with a typical ankle sprain?","Higher up between the shin bones, not just below the outer ankle."],["How did the injury occur?","My foot was planted and the body turned outward."],["Can you bear weight, and is there marked swelling?","I can limp a few steps; pushing off is painful."]],findings:["Tenderness over the distal tibiofibular syndesmosis.","External-rotation loading reproduces pain; test cautiously and do not rely on a single squeeze/external-rotation test.","Assess malleolar tenderness, weight-bearing and possible associated fracture."],examPrompt:"What makes a syndesmotic injury important to identify early?",examReason:"High ankle sprains can have a longer recovery and may involve instability. Fracture or syndesmotic instability requires medical assessment; provocative tests alone cannot grade the injury.",diagnosis:"Suspected syndesmotic (high ankle) sprain",diagnosisReason:"The external-rotation mechanism and pain above the ankle are compatible with syndesmotic injury. Stability and fracture status need assessment before rehabilitation loading.",differentials:[{diagnosis:"Lateral ankle ligament sprain",reasoning:"Usually follows inversion and produces more focal lateral ligament-region tenderness."},{diagnosis:"Ankle fracture",reasoning:"Focal bony tenderness or inability to bear weight under decision-rule criteria warrants imaging."}],management:["Stop cutting/jumping and arrange medical assessment/imaging when fracture or unstable syndesmosis is suspected.","Use protection and weight-bearing guidance according to assessment/medical advice; avoid forceful stress testing.","Rehabilitation progresses through range, strength, balance, running and cutting only when symptoms and stability permit."],progression:["Track pain on push-off, gait, swelling, calf strength and dynamic control.","Return to football only after progressive running/cutting tasks are tolerated and instability has been excluded."],learning:["Pain above the ankle after external rotation is a different injury pattern.","High ankle sprains may take longer than lateral sprains.","Exclude fracture and instability before loading."],references:[jn("Syndesmotic ankle injury clinical guideline","syndesmotic ankle sprain diagnosis management consensus guideline"),aaos("Sprained ankle","https://orthoinfo.aaos.org/en/diseases--conditions/sprained-ankle/")]},
{id:"expanded-33-1",category:"MSK & Sports",patient:"Naveed Iqbal, 33 · recreational runner",opening:"The back of my heel has gradually become painful during running and hopping. It is stiff when I first get moving but I can still walk.",scene:["Naveed increased hill running and sprint work over three weeks. The presentation is gradual load-related tendon pain, not a sudden rupture story.","Check location, tendon integrity, training load and alternative causes before prescribing high-load calf work."],history:[["Was there a sudden snap or immediate loss of push-off?","No snap; the pain built up over weeks."],["Where is the pain and what loads it?","A few centimetres above the heel; hills, hopping and fast running hurt."],["Any recent fluoroquinolone use, steroid exposure or other tendon risk?","No known recent medication change; this should be confirmed in a real assessment."]],findings:["Localized Achilles tendon tenderness with load-related pain.","Calf raises/hopping reproduce symptoms; assess calf capacity and tendon continuity if rupture is a concern.","Differentiate midportion from insertional symptoms because loading range may need modification."],examPrompt:"What history finding most strongly separates tendinopathy from acute Achilles rupture?",examReason:"Gradual load-related pain without sudden snap or immediate push-off failure supports tendinopathy. Acute snap, marked weakness or abnormal Thompson test requires urgent assessment for rupture.",diagnosis:"Achilles tendinopathy, location to be specified as midportion or insertional",diagnosisReason:"The gradual onset and load-sensitive tendon pain fit tendinopathy. Location and irritability determine the loading plan; imaging is not automatically required for a typical presentation.",differentials:[{diagnosis:"Achilles tendon rupture",reasoning:"Sudden snap, immediate loss of push-off, palpable gap or abnormal calf-squeeze response warrants urgent assessment."},{diagnosis:"Retrocalcaneal bursitis or other posterior heel pathology",reasoning:"Insertional pain, swelling and shoe-pressure sensitivity may indicate an adjacent structure or coexisting condition."}],management:["Adjust hill/sprint volume while maintaining tolerable activity; avoid abrupt complete rest if safe.","Use progressive calf strengthening tailored to insertional versus midportion symptoms and irritability; increase load over time.","Refer for medical assessment if rupture is suspected, symptoms are atypical or function deteriorates markedly."],progression:["Track calf-raise capacity, hopping and next-day response; reintroduce running speed and hills in staged increments.","Return to high-speed running only after strength and energy-storage tasks are tolerated."],learning:["Training-load changes matter in tendon pain.","Tendinopathy and rupture have different onset patterns and urgency.","Exercise dosage must match tendon location and irritability."],references:[jn("Achilles tendinopathy clinical practice guideline rehabilitation","Achilles pain stiffness muscle power deficits clinical practice guideline revision 2024"),aaos("Achilles tendon disorders","https://orthoinfo.aaos.org/en/diseases--conditions/achilles-tendinitis/")]},
{id:"expanded-34-1",category:"Clinical Red Flags",patient:"Naveed Iqbal, 33 · recreational runner",opening:"During a sprint I felt a sudden snap behind my ankle, and now I cannot push off or rise onto my toes properly.",scene:["This is a separate acute presentation from gradual Achilles tendinopathy. A sudden snap with loss of push-off raises concern for rupture and should not be treated with routine tendon loading.","Avoid repeated hopping or forceful testing; arrange urgent assessment and protect the limb according to local protocol."],history:[["Was onset sudden or gradual?","Sudden, during acceleration."],["Could you continue running or push off afterward?","No, I stopped immediately and walking is difficult."],["Any previous Achilles pain or recent risk factors?","I had no major pain before this."]],findings:["Acute posterior ankle/calf event with marked push-off weakness.","A clinician may find an abnormal calf-squeeze (Thompson) response; a single test is interpreted with the full presentation.","Assess skin, swelling, neurovascular status and associated injury without delaying referral."],examPrompt:"What is the immediate management priority when Achilles rupture is suspected?",examReason:"Sudden snap and loss of push-off require prompt medical/orthopaedic assessment. Do not prescribe heel raises, stretching or repeated provocative tests before the rupture pathway is addressed.",diagnosis:"Suspected acute Achilles tendon rupture",diagnosisReason:"The sudden onset and immediate functional loss are concerning for rupture. Confirmation and immobilization/management decisions belong in the urgent medical pathway.",differentials:[{diagnosis:"Acute calf muscle tear",reasoning:"Can also cause a sudden posterior leg pain but must be distinguished by examination; do not assume a muscle strain."},{diagnosis:"Severe ankle sprain or fracture",reasoning:"Trauma, bony tenderness, deformity or inability to bear weight may require imaging and urgent assessment."}],management:["Stop running and arrange urgent same-day medical/orthopaedic assessment according to local pathway.","Protect the limb and avoid stretching or loading the tendon; follow local advice for immobilization and safe mobility.","Document onset, functional loss, examination findings and neurovascular status; do not delay referral to complete a routine session."],progression:["Rehabilitation begins only within a confirmed rupture-management plan and must follow the treating team's precautions.","Monitor wound/skin, swelling, safe mobility and later functional recovery as directed by the medical team."],learning:["Acute rupture is not tendinopathy.","A positive or negative single test should not delay referral when the history is compelling.","Early protection and appropriate medical assessment matter."],urgent:true,references:[jn("Achilles tendon rupture acute management guideline","Achilles tendon rupture diagnosis management guideline Thompson test"),aaos("Achilles tendon rupture","https://orthoinfo.aaos.org/en/diseases--conditions/achilles-tendon-rupture/")]},
{id:"expanded-35-1",category:"MSK & Sports",patient:"Mehwish Noor, 42 · retail worker",opening:"My heel hurts most during the first few steps in the morning, then eases a little as I walk, but long shifts bring it back.",scene:["Mehwish's pain is plantar-medial and load-related. Screen for neuropathic, inflammatory, stress injury and systemic causes rather than treating all heel pain as plantar fasciopathy.","The case emphasizes progressive load management and footwear/activity discussion."],history:[["Where is the pain?","Under the inner side of the heel."],["When is it worst?","First steps after rest, then again after standing for hours."],["Any trauma, night/rest pain, fever, numbness or sudden inability to bear weight?","No trauma or fever; no numbness."]],findings:["Familiar tenderness at the medial plantar heel region.","First-step pain and prolonged-standing aggravation are reported.","Assess ankle dorsiflexion, calf capacity, foot function and neural/systemic signs when indicated."],examPrompt:"Which pattern supports plantar heel pain while keeping other causes in view?",examReason:"First-step pain and medial plantar heel tenderness are compatible with plantar fasciopathy, but symptoms are not pathognomonic. Night/rest pain, systemic symptoms, trauma or neurological signs change the assessment.",diagnosis:"Probable plantar fasciopathy (plantar heel pain)",diagnosisReason:"The first-step and prolonged-load pattern with medial plantar heel tenderness supports plantar fasciopathy; the diagnosis remains provisional after screening alternatives.",differentials:[{diagnosis:"Calcaneal stress injury",reasoning:"Progressive pain with weight bearing, impact increase or bone-health risk requires medical assessment and may warrant imaging."},{diagnosis:"Tarsal tunnel or peripheral nerve irritation",reasoning:"Burning, tingling or sensory change suggests a neural contributor rather than isolated plantar fascia pain."}],management:["Discuss load modification for long shifts and comfortable supportive footwear without prescribing one universal shoe.","Use plantar fascia/calf stretching and progressive foot/calf strengthening tailored to tolerance; consider taping or orthoses as adjuncts when appropriate.","Refer for assessment if pain is atypical, progressive at rest, associated with systemic features or not following the expected course."],progression:["Track first-step pain, standing tolerance and walking function; progress strengthening and work exposure gradually.","Reassess the diagnosis if sensory symptoms or worsening night/rest pain appears."],learning:["First-step pain is useful but not diagnostic by itself.","Workload and standing exposure are important targets.","Screen for stress injury and neural causes."],references:[jn("Plantar heel pain clinical practice guideline","heel pain plantar fasciitis clinical practice guideline revision 2023 physical therapy"),aaos("Plantar fasciitis","https://orthoinfo.aaos.org/en/diseases--conditions/plantar-fasciitis/")]},
{id:"expanded-36-1",category:"Clinical Red Flags",patient:"Ashraf Khan, 63 · shop owner with diabetes",opening:"Since last night my knee has become hot, swollen and extremely painful. I have a fever and cannot put weight on it.",scene:["Ashraf has an acutely hot swollen joint and systemic illness. Septic arthritis is a medical emergency until excluded; do not perform routine exercise or attempt to 'work the swelling out'.","Diabetes increases concern but the emergency pattern matters regardless of risk factors."],history:[["When did the swelling begin, and was there an injury?","It started overnight without an injury."],["Any fever, chills or feeling unwell?","My temperature is 38.8°C and I feel unwell."],["Can you bear weight or tolerate gentle movement?","No, even small movement is severely painful."]],findings:["Hot, swollen knee with severe pain and markedly painful passive movement.","Fever/systemic illness and inability to bear weight are reported.","The presentation requires urgent medical assessment; do not wait for a physiotherapy test to confirm infection."],examPrompt:"What is the correct action when septic arthritis is possible?",examReason:"A hot swollen joint with fever and severe movement pain needs urgent same-day emergency medical evaluation for aspiration, investigations and treatment. Do not treat it as a routine flare of osteoarthritis or crystal arthritis.",diagnosis:"Suspected septic arthritis — emergency medical assessment required",diagnosisReason:"The acute hot swollen joint plus fever, severe pain and inability to bear weight is a high-risk infection pattern. Diagnosis requires urgent medical work-up; physiotherapy must not delay it.",differentials:[{diagnosis:"Crystal arthritis (gout/pseudogout)",reasoning:"Can cause an acutely hot swollen joint, but infection must be excluded urgently and the two can coexist."},{diagnosis:"Inflammatory arthritis flare",reasoning:"May cause swelling and pain but systemic fever and a new severely painful joint still require urgent evaluation."}],management:["Stop routine physiotherapy and arrange immediate emergency medical assessment via local pathway.","Communicate fever, onset, joint warmth/swelling, pain with passive movement, inability to bear weight and relevant comorbidities.","Do not apply exercise, manual therapy, heat or delay escalation while waiting for symptom response."],progression:["Physiotherapy is reconsidered only after medical diagnosis and treatment with explicit guidance on joint loading and precautions.","Any deterioration while awaiting transfer requires emergency escalation."],learning:["Septic arthritis is time-critical.","A hot swollen joint with fever is not a routine musculoskeletal case.","Referral is the correct clinical intervention."],urgent:true,references:[jn("Septic arthritis emergency diagnosis guideline","septic arthritis native joint guideline emergency diagnosis management"),nice("Osteoarthritis in over 16s: diagnosis and management (NG226)","https://www.nice.org.uk/guidance/ng226/chapter/Recommendations")]},
{id:"multi-neuro-parkinson-1",category:"Neurological Rehabilitation",patient:"Rashid Mahmood, 70 · retired accountant",opening:"When I walk through a doorway or turn quickly, my feet seem to freeze. I am afraid of falling.",scene:["Rashid has a medical diagnosis of Parkinson's disease and reports episodic freezing of gait. The physiotherapist must understand triggers, medication timing, falls risk and functional goals.","Do not treat freezing as weakness alone; look at context, cueing response and safe task practice."],history:[["When does freezing occur?","Doorways, tight turns and crowded places are the worst."],["Does it vary with medication timing or fatigue?","It is worse just before my next dose and when tired."],["Any recent falls, fainting or sudden new neurological symptoms?","I fell once last month; no fainting or sudden new symptoms."]],findings:["Freezing episodes are triggered by doorways and turning.","Turning and dual-task gait increase instability; assess falls history, gait, transfers and orthostatic symptoms.","Review medication timing with the medical team; physiotherapy does not adjust medication."],examPrompt:"Which assessment best links freezing to a safe, functional rehabilitation plan?",examReason:"Observe gait and turns under safe conditions, identify triggers and test external cueing without provoking a fall. Screen for orthostatic hypotension and other contributors.",diagnosis:"Parkinson's disease with freezing of gait and elevated falls risk",diagnosisReason:"The known diagnosis and context-specific freezing are consistent with Parkinsonian gait dysfunction. Falls risk and medication fluctuations require multidisciplinary coordination.",differentials:[{diagnosis:"Orthostatic hypotension",reasoning:"Light-headedness or symptoms on standing require lying/standing blood-pressure assessment and medical review."},{diagnosis:"Other neurological deterioration",reasoning:"Sudden new weakness, acute gait loss or a new focal deficit requires urgent medical assessment rather than attribution to Parkinson's."}],management:["Train external cueing strategies (visual floor targets, rhythm or deliberate weight shift) matched to the patient's trigger and response.","Practice turning, doorway passage and transfers with appropriate guarding and environmental setup.","Coordinate medication-timing concerns, falls review and home-safety assessment with the multidisciplinary team."],progression:["Track freezing frequency, near-falls, turning performance and confidence in meaningful environments.","Progress from predictable practice to more complex real-world tasks only when safe."],learning:["Freezing is context-dependent and not simply a strength deficit.","Cueing should be tested individually.","Falls, orthostatic symptoms and medication timing deserve screening."],references:[jn("Parkinson disease physiotherapy guideline freezing gait","Parkinson disease physiotherapy clinical practice guideline gait freezing external cueing"),nice("Parkinson's disease in adults (NG71)","https://www.nice.org.uk/guidance/ng71/chapter/recommendations")]},
{id:"multi-peds-torticollis-1",category:"Pediatric Rehabilitation",patient:"Ayaan, 4 months · infant, accompanied by parent",opening:"He always looks to the right, and turning his head to the left seems harder. One side of his head is becoming flatter.",scene:["Ayaan's parent noticed a consistent head-turn preference from early infancy. The clinician needs a developmental and musculoskeletal assessment, not a generic stretching prescription.","Screen for atypical neurological, visual, spinal or systemic features and refer when the presentation is not consistent with muscular torticollis."],history:[["When did you first notice the head preference?","Around the first few weeks; it is still present."],["How does he feed, track faces and move both arms and legs?","Feeding is okay, but he prefers looking to the right."],["Any fever, pain, sudden onset or unusual eye movements?","No fever or sudden change."]],findings:["Consistent head-turn preference with reduced comfortable rotation toward the left.","Assess cervical passive/active range, head tilt, sternocleidomastoid, cranial shape, symmetry and age-appropriate motor development.","Visual tracking, tone, neurological status and red flags must be screened."],examPrompt:"What makes a torticollis presentation atypical and worthy of medical review?",examReason:"Atypical onset, pain, acute change, neurological signs, abnormal ocular movements or a presentation not fitting muscular torticollis warrants medical evaluation. Treatment is individualized to the infant's age and findings.",diagnosis:"Suspected congenital muscular torticollis with positional cranial asymmetry",diagnosisReason:"Early head preference and asymmetric cervical rotation are compatible with torticollis, but a full infant assessment is required to exclude non-muscular causes and characterize cranial asymmetry.",differentials:[{diagnosis:"Ocular torticollis",reasoning:"Abnormal eye alignment or tracking may drive head position and needs appropriate medical/vision assessment."},{diagnosis:"Neurological or structural cause",reasoning:"Abnormal tone, developmental regression, pain or atypical onset warrants pediatric medical review."}],management:["Teach caregiver-led, gentle positioning and symmetrical active movement during play and feeding; do not force the infant's neck.","Use supervised prone play while awake, vary carrying/feeding positions and avoid unsafe sleep positioning; sleep remains supine on a safe surface.","Refer to pediatric medical care for atypical signs and coordinate early pediatric physiotherapy; consider cranial-shape review when indicated."],progression:["Measure cervical range, head tilt, active tracking, motor symmetry and caregiver confidence at follow-up.","Adjust the home program to the infant's response; refer if progress stalls or new signs appear."],learning:["Infant torticollis needs developmental and red-flag screening.","Caregiver education and active symmetrical play are central.","Never recommend unsafe sleep positioning."],references:[jn("Congenital muscular torticollis clinical practice guideline","congenital muscular torticollis clinical practice guideline pediatric physical therapy 2018"),jn("Infant positional plagiocephaly and torticollis evidence","congenital muscular torticollis infant physical therapy guideline")]},
{id:"multi-cardio-asthma-1",category:"Cardiopulmonary Rehabilitation",patient:"Hira Saleem, 19 · university badminton player",opening:"During fast rallies I start coughing and wheezing, and I need several minutes to recover. I feel fine at rest.",scene:["Hira reports exercise-associated respiratory symptoms with no current distress at rest. Exercise-induced bronchoconstriction is possible, but diagnosis and medication planning belong with the medical team.","The physiotherapist must screen control, rescue plan and warning signs before exercise progression."],history:[["When do symptoms occur in relation to exercise?","Usually during intense rallies or soon afterward, especially in cold air."],["Has asthma or exercise-induced bronchoconstriction been medically assessed?","I was told I may have asthma, but my plan needs review."],["Any severe breathlessness at rest, blue lips, difficulty speaking or poor response to prescribed reliever?","Not now; during the worst episode I had to stop completely."]],findings:["Symptoms are exertional and episodic; no acute respiratory distress is present at the teaching encounter.","Review medical diagnosis, prescribed action plan, inhaler technique by the appropriate clinician and environmental triggers.","Do not diagnose asthma from symptoms alone; objective respiratory assessment may be needed."],examPrompt:"What must be established before planning exercise for suspected exercise-induced bronchoconstriction?",examReason:"Confirm the medical assessment and asthma action plan, current control and emergency signs. Severe breathlessness, difficulty speaking or poor response to reliever requires urgent/emergency care.",diagnosis:"Exercise-associated bronchoconstriction suspected; asthma control requires medical review",diagnosisReason:"The exertional cough/wheeze pattern is compatible but not diagnostic. The plan should coordinate with medical assessment and avoid unsupervised medication changes.",differentials:[{diagnosis:"Exercise-induced laryngeal obstruction",reasoning:"Inspiratory noise/throat tightness during peak exercise with rapid recovery can suggest an alternative that needs appropriate assessment."},{diagnosis:"Cardiac or other respiratory cause",reasoning:"Chest pain, syncope, disproportionate dyspnoea or unusual oxygen response requires medical assessment."}],management:["Confirm that Hira has an up-to-date clinician-provided action plan and knows when to stop exercise and seek help.","Once medically appropriate, use a graded warm-up and individualized training progression; avoid prescribing or changing medication doses.","Stop exercise and follow the action plan if symptoms occur; emergency features require urgent help."],progression:["Track symptom timing, recovery, exercise tolerance and any episodes; coordinate with the treating clinician if symptoms recur.","Progress intensity only when symptoms are controlled and the medical plan is clear."],learning:["Exercise-related wheeze needs medical assessment, not assumption.","Physiotherapists do not independently change asthma medication.","An action plan and emergency recognition are part of exercise safety."],references:[jn("Exercise-induced bronchoconstriction clinical practice guideline","exercise-induced bronchoconstriction diagnosis management ATS guideline"),nice("Asthma: diagnosis, monitoring and chronic asthma management (NG245)","https://www.nice.org.uk/guidance/ng245/chapter/Recommendations")]},
{id:"multi-cardio-hf-1",category:"Cardiopulmonary Rehabilitation",patient:"Rafiq Ahmed, 69 · retired bank manager",opening:"I get short of breath climbing one flight of stairs, but my symptoms have been stable since the cardiology review.",scene:["Rafiq has diagnosed stable heart failure and wants to walk to the local mosque with fewer stops. The session must confirm stability, medication/team plan and exercise response before progressing.","New rest dyspnoea, chest pain, syncope or rapid fluid-related weight gain changes the plan."],history:[["Have symptoms changed recently?","No new rest breathlessness, chest pain or fainting."],["Any rapid weight gain, worsening ankle swelling or need for extra pillows?","My ankles are mildly swollen but unchanged; my team monitors my weight."],["What activity goal matters most?","Walking to the mosque and back with fewer stops."]],findings:["Exertional limitation is reported in a medically diagnosed heart-failure patient who is currently described as stable.","Check resting symptoms, blood pressure, heart rate, oxygen saturation when indicated, perceived exertion and signs of decompensation.","Exercise prescription must align with the cardiology plan and comorbidities."],examPrompt:"What signs would make you defer exercise and seek medical review?",examReason:"New/worsening rest dyspnoea, chest pain, syncope, rapid fluid-related weight gain or worsening oedema may indicate decompensation. Exercise training is for appropriately assessed stable patients.",diagnosis:"Stable chronic heart failure with reduced exercise tolerance, pending session safety check",diagnosisReason:"The known diagnosis and exertional limitation fit a rehabilitation need, but stability must be reconfirmed at every session rather than assumed from the referral.",differentials:[{diagnosis:"Acute heart-failure decompensation",reasoning:"Worsening breathlessness, orthopnoea, oedema or rapid weight gain requires prompt medical contact and exercise deferral."},{diagnosis:"Pulmonary or musculoskeletal contributor",reasoning:"Unexpected oxygen changes, cough, chest symptoms or focal pain may require separate assessment."}],management:["Confirm current stability and the clinician-provided exercise/monitoring plan before exercise; defer and contact the medical team if decompensation is suspected.","For stable patients, use individualized aerobic and resistance exercise with symptom, exertion and vital-sign monitoring appropriate to risk.","Teach pacing and symptom self-monitoring without giving medication or fluid-management instructions outside the medical plan."],progression:["Track walking distance, perceived exertion, symptoms and recovery; increase one training variable at a time.","Escalate if exercise tolerance drops unexpectedly or new cardiopulmonary warning signs develop."],learning:["Stable heart failure rehabilitation is different from acute decompensation.","Check status at each session, not only at intake.","Progression should be individualized and coordinated with the care team."],references:[jn("Heart failure exercise rehabilitation guideline","heart failure exercise training rehabilitation clinical practice guideline"),nice("Chronic heart failure in adults (NG106)","https://www.nice.org.uk/guidance/ng106/chapter/recommendations")]},
{id:"multi-vest-posterior-1",category:"Vestibular Rehabilitation",patient:"Nazia Parveen, 58 · shopkeeper",opening:"When I roll onto my right side in bed or look upward, the room spins for a few seconds and then settles.",scene:["Nazia describes brief, position-triggered vertigo without continuous symptoms. A positional vestibular disorder is possible, but central and neurological red flags must be screened.","Do not prescribe a repositioning manoeuvre until the history, positional test findings and contraindications are considered."],history:[["How long does each spinning episode last?","Usually under a minute after rolling or looking up."],["Any new severe headache, double vision, weakness, slurred speech or inability to walk?","No, none of those."],["Any hearing loss, ear symptoms or continuous dizziness?","No new hearing loss and I feel normal between episodes."]],findings:["Brief position-triggered vertigo with symptom-free intervals.","Posterior-canal BPPV requires a compatible positional history and characteristic positional nystagmus on Dix–Hallpike testing when safe.","Screen cervical mobility/contraindications and central neurological features before positional testing."],examPrompt:"What evidence is needed before calling this posterior-canal BPPV?",examReason:"A compatible history plus characteristic positional nystagmus on the appropriate test supports BPPV. A symptom report alone is insufficient; central signs or atypical persistent symptoms need medical assessment.",diagnosis:"Suspected right posterior-canal benign paroxysmal positional vertigo",diagnosisReason:"Brief vertigo with rolling and looking up is compatible, but side and canal must be confirmed by positional examination.",differentials:[{diagnosis:"Vestibular migraine",reasoning:"Episodes may last longer and associate with migraine features or sensory sensitivity."},{diagnosis:"Central vestibular disorder",reasoning:"New neurological signs, severe gait inability, persistent acute vertigo or atypical nystagmus warrants urgent medical assessment."}],management:["Perform an appropriate positional assessment only if safe and within competence; document observed nystagmus and symptom pattern.","If posterior-canal BPPV is confirmed and no contraindication exists, use a canalith-repositioning manoeuvre appropriate to the affected side.","Provide advice about recurrence and safety; urgent neurological red flags require immediate medical evaluation."],progression:["Reassess positional symptoms and, when indicated, repeat positional testing after treatment.","If symptoms persist, recur atypically or do not fit the expected pattern, reassess canal involvement and refer as appropriate."],learning:["Brief positional vertigo suggests but does not prove BPPV.","Observed nystagmus and canal-specific testing matter.","Screen for central red flags before manoeuvres."],references:[jn("BPPV clinical practice guideline update","benign paroxysmal positional vertigo clinical practice guideline update 2017"),jn("Vestibular rehabilitation evidence guideline","vestibular rehabilitation clinical practice guideline peripheral vestibular hypofunction")]},
{id:"multi-onc-cipn-1",category:"Oncology Rehabilitation",patient:"Saira Bukhari, 55 · breast cancer survivor receiving neurotoxic chemotherapy",opening:"Since chemotherapy, my feet feel numb and I am less steady on uneven ground. I have started avoiding evening walks.",scene:["Saira reports distal sensory changes temporally associated with chemotherapy. Confirm treatment context with the oncology team and assess falls risk, sensation and functional mobility.","Do not assume all symptoms are treatment-related; rapidly progressive or asymmetric neurological changes require medical assessment."],history:[["When did numbness start and is it changing?","It began during treatment and has gradually become more noticeable."],["Any falls, weakness, severe pain or symptoms in the hands too?","No falls yet; my feet are worst and my fingertips sometimes tingle."],["Any sudden one-sided weakness, new bladder/bowel symptoms or severe back pain?","No." ]],findings:["Distal sensory symptoms with impaired balance on uneven surfaces.","Assess protective sensation, proprioception, gait, balance, footwear/skin risk and strength.","Review fall history, medications and other neuropathy causes with the medical team."],examPrompt:"Which risks need addressing before progressing balance and gait tasks?",examReason:"Reduced protective sensation increases fall and foot-injury risk. Screen for skin injury, weakness, orthostatic symptoms and rapid neurological change; coordinate with oncology.",diagnosis:"Suspected chemotherapy-induced peripheral neuropathy with balance impairment",diagnosisReason:"The temporal relationship and distal sensory pattern are compatible with chemotherapy-induced peripheral neuropathy, but other causes and severity require medical review.",differentials:[{diagnosis:"Diabetic or other metabolic neuropathy",reasoning:"Pre-existing diabetes, nutritional issues or other conditions may contribute and should be reviewed."},{diagnosis:"Spinal or central neurological pathology",reasoning:"Asymmetry, rapid progression, focal weakness or new sphincter symptoms requires prompt medical assessment."}],management:["Coordinate with the oncology team and document sensory/balance status; check footwear and feet for skin injury.","Use graded balance, lower-limb strength and gait training with appropriate guarding and environmental safety.","Educate about daily foot checks, safe lighting/footwear and when to report worsening numbness, pain or weakness."],progression:["Track gait/balance measures, near-falls, sensory change and participation; increase challenge only with safe guarding.","Refer promptly for new focal weakness, rapid progression, skin injury or other atypical features."],learning:["CIPN affects sensation, balance and safety—not only pain.","Foot protection and falls prevention are core components.","Coordinate rehabilitation with oncology and investigate atypical change."],references:[jn("Chemotherapy-induced peripheral neuropathy rehabilitation and exercise","chemotherapy induced peripheral neuropathy rehabilitation exercise balance guideline"),jn("Cancer rehabilitation peripheral neuropathy","cancer rehabilitation chemotherapy induced peripheral neuropathy guideline")]},
{id:"multi-icu-weakness-1",category:"Critical Care & ICU",patient:"Saleem Akhtar, 62 · recovering after prolonged ICU admission",opening:"I survived a serious infection, but now even sitting up and standing take much more effort than before.",scene:["Saleem is recovering after prolonged critical illness and has marked deconditioning. Before mobilization, review current medical stability, lines/tubes, cognition, oxygenation and the ICU team's restrictions.","ICU-acquired weakness is a working hypothesis after exclusion of other neurological, cardiac and respiratory causes."],history:[["What could you do before admission?","I was independent and walked daily."],["What currently limits movement?","My legs feel weak and I become tired quickly."],["Any new chest pain, fainting, worsening breathlessness or confusion today?","No new chest pain or fainting; the ward team says I am stable for assessment."]],findings:["Generalized weakness and reduced functional endurance after prolonged critical illness.","Assess alertness, command following, respiratory/cardiovascular response, lines/tubes and safe transfer ability before activity.","Look for asymmetry, focal deficits, severe pain or other findings inconsistent with generalized weakness."],examPrompt:"What needs to be checked before the first mobilization session?",examReason:"Readiness depends on current physiological stability, device/line safety, alertness and team instructions. Stop for concerning physiological response or new symptoms; do not mobilize by a fixed protocol alone.",diagnosis:"Post-critical-illness functional weakness and deconditioning; ICU-acquired weakness is a possible contributor",diagnosisReason:"The generalized weakness after prolonged critical illness is compatible, but diagnosis and mobility readiness require full multidisciplinary review.",differentials:[{diagnosis:"Focal neurological event",reasoning:"New asymmetry, facial/arm weakness or altered speech requires urgent assessment."},{diagnosis:"Ongoing cardiopulmonary instability",reasoning:"Worsening oxygenation, hemodynamic instability, chest pain or syncope means defer mobilization and alert the medical team."}],management:["Confirm readiness and precautions with the ICU/ward team; coordinate lines, tubes, oxygen and staff assistance before movement.","Begin with an appropriate low-level activity such as bed mobility, sitting or supported standing only if stable, monitoring symptoms and vital response.","Use short, repeated functional activity and rest periods; stop and escalate for instability or new symptoms."],progression:["Progress from bed mobility to sitting, transfers and walking according to daily stability and response.","Track assistance level, strength, fatigue and functional milestones; reassess for atypical or focal deficits."],learning:["ICU rehabilitation is a safety decision before it is an exercise prescription.","Team communication and device management are essential.","Generalized weakness must not mask a new focal or medical problem."],references:[jn("ICU early mobilization clinical practice guideline","ICU early mobilization rehabilitation clinical practice guideline safety criteria"),jn("ICU-acquired weakness rehabilitation evidence","ICU acquired weakness rehabilitation physical therapy guideline")]},
{id:"multi-cardio-bronchiectasis-1",category:"Cardiopulmonary Rehabilitation",patient:"Mariam Yousaf, 46 · office administrator",opening:"I produce a lot of sputum most mornings and feel chest congestion makes walking and daily tasks harder.",scene:["Mariam has diagnosed bronchiectasis and wants to manage sputum and activity more effectively. Airway-clearance techniques must be individualized to secretion burden, symptoms and respiratory-team guidance.","New haemoptysis, acute deterioration, fever or disproportionate breathlessness changes the plan."],history:[["How much sputum do you produce, and has it changed colour or volume recently?","Most mornings; it is usual for me and has not suddenly increased."],["Any blood in sputum, fever, chest pain or acute breathlessness?","No blood or fever today."],["Which airway-clearance technique has been taught and does it help?","I was shown a breathing technique but need it reviewed."]],findings:["Chronic sputum production with known bronchiectasis.","Assess respiratory rate, breathlessness, cough effectiveness, sputum pattern and exercise tolerance; coordinate with respiratory team.","Check for exacerbation signs and haemoptysis before airway-clearance or exercise progression."],examPrompt:"What would make this a possible exacerbation requiring medical review rather than routine airway-clearance training?",examReason:"Increased sputum volume/purulence, worsening cough or breathlessness, fever, haemoptysis or systemic illness can indicate exacerbation or complication and require medical review.",diagnosis:"Stable bronchiectasis with chronic sputum-clearance and exercise-tolerance needs",diagnosisReason:"The reported chronic pattern is compatible with stable bronchiectasis, but stability must be checked and airway clearance tailored by a trained clinician.",differentials:[{diagnosis:"Acute infective exacerbation",reasoning:"A clear change from baseline in sputum, cough, breathlessness or systemic symptoms warrants prompt respiratory-team review."},{diagnosis:"Significant haemoptysis or other acute pathology",reasoning:"Blood in sputum, chest pain or acute deterioration needs urgent medical assessment."}],management:["Review and teach the prescribed airway-clearance technique, checking comfort, effectiveness and the patient's understanding.","Add individualized aerobic and strength activity when stable; coordinate airway clearance around activity according to symptoms and the respiratory plan.","Provide explicit instructions to seek medical review for exacerbation signs or haemoptysis."],progression:["Track sputum burden, breathlessness, activity tolerance and technique effectiveness; adjust with respiratory-team input.","Defer progression and seek review when symptoms deviate from baseline."],learning:["Airway clearance should be individualized, not one-size-fits-all.","Change from baseline is more informative than sputum alone.","Haemoptysis and acute deterioration need escalation."],references:[jn("Bronchiectasis airway clearance physiotherapy guideline","bronchiectasis airway clearance physiotherapy guideline ERS adult"),jn("Bronchiectasis adult management guideline","European Respiratory Society bronchiectasis guideline adults airway clearance")]},
{id:"multi-peds-dcd-1",category:"Pediatric Rehabilitation",patient:"Zara, 8 years · school-age child, accompanied by parent",opening:"I want to join games at school, but I am slower than classmates when catching balls, learning new movements or tying my laces.",scene:["Zara's parent and teacher describe persistent coordination difficulties affecting school and play. Developmental coordination disorder requires multidisciplinary diagnostic assessment and exclusion of other causes.","Therapy should focus on meaningful activity and participation, not repetitive impairment drills without a functional goal."],history:[["When did you notice coordination difficulties?","Since early school years; they affect dressing, handwriting and playground games."],["Does it affect more than one setting?","Yes, home and school both notice it."],["Any regression, marked weakness, pain or loss of previously acquired skills?","No loss of skills; she has always found these tasks harder."]],findings:["Motor coordination difficulty affects daily activities and school/play participation.","Assess functional tasks, motor planning, balance, strength and the child's own goals in a supportive environment.","Developmental history and exclusion of neurological, visual or other causes require appropriate multidisciplinary input."],examPrompt:"What evidence is needed before assigning a developmental coordination disorder label?",examReason:"A diagnosis requires age-inappropriate motor skill acquisition/execution with meaningful functional impact and exclusion of other medical/developmental explanations; a physiotherapy session alone should not overstate diagnostic certainty.",diagnosis:"Coordination-related functional difficulty; developmental coordination disorder requires multidisciplinary confirmation",diagnosisReason:"The persistent cross-setting motor difficulties and participation impact raise DCD as a possibility, but formal diagnostic criteria and differential assessment are required.",differentials:[{diagnosis:"Neurological or neuromuscular condition",reasoning:"Regression, focal weakness, abnormal tone or progressive loss of skills requires medical assessment."},{diagnosis:"Visual, attention or learning-related contributor",reasoning:"Vision, attention and learning needs can affect task performance and should be considered with the family and school."}],management:["Choose child-selected goals such as tying laces or joining a playground game and practice the actual task in manageable steps.","Use task-oriented, repeated practice with feedback and adapt school/home environments to support participation.","Coordinate with parents, teachers and relevant clinicians; avoid framing the child as lazy or unmotivated."],progression:["Track task success, independence, confidence and participation across home and school.","Increase task complexity gradually and revisit goals with the child and family."],learning:["DCD is a diagnosis requiring appropriate criteria and exclusion of alternatives.","Participation-focused task practice is central.","Family and school context materially affect rehabilitation."],references:[jn("Developmental coordination disorder clinical recommendations","developmental coordination disorder international clinical practice recommendations children physical therapy"),jn("DCD task-oriented intervention evidence","developmental coordination disorder task oriented intervention guideline children")]},
{id:"multi-ger-osteoporosis-1",category:"Geriatrics & Falls",patient:"Begum Salma, 76 · retired homemaker",opening:"I have osteoporosis and worry about bending or lifting because I was told my bones are fragile. I also feel less steady on stairs.",scene:["Salma has osteoporosis and fear of movement. The plan must address fracture history, falls risk, safe loading and confidence without giving blanket restrictions that increase deconditioning.","New severe focal spinal pain after minor trauma or sudden functional loss requires medical assessment before exercise."],history:[["Have you had a fragility fracture or recent fall?","I fractured my wrist two years ago and had one near-fall last month."],["Any new back pain after a small movement or fall?","No new back pain today."],["Which activities are you avoiding?","Carrying groceries and using stairs without holding the rail."]],findings:["Known osteoporosis with previous fragility fracture and reduced confidence in stairs/lifting.","Assess balance, lower-limb strength, gait, transfer strategy, falls risks and spinal symptoms.","Exercise selection should consider fracture history, posture, balance and the patient's medical plan."],examPrompt:"How can exercise be promoted without ignoring fracture risk?",examReason:"Osteoporosis is not a reason for blanket inactivity. Tailor progressive resistance, balance and weight-bearing exercise to fracture history and ability; avoid high-risk loaded spinal flexion/twisting when inappropriate and refer for new focal pain after minor trauma.",diagnosis:"Osteoporosis with falls risk and movement-related fear",diagnosisReason:"The known osteoporosis and prior fragility fracture are established risk context; current functional concerns call for individualized falls prevention and safe exercise planning, not a new structural diagnosis.",differentials:[{diagnosis:"Occult vertebral fracture",reasoning:"New focal severe spinal pain after minor trauma or sudden loss of function warrants prompt medical assessment."},{diagnosis:"Vestibular or cardiovascular contributor to instability",reasoning:"Vertigo, faintness or symptoms on standing require targeted assessment and possible medical review."}],management:["Review fracture history and precautions with the medical team where needed; refer promptly if new focal spinal pain or suspected fracture appears.","Use individualized progressive resistance, balance and functional training with safe technique, support and graded confidence-building.","Discuss home hazards, footwear and appropriate supports; coordinate osteoporosis and falls care with the wider team."],progression:["Track balance, chair-rise performance, stair confidence and near-falls; progress load and balance challenge gradually.","Reassess after any fall, new pain or dizziness and modify the plan based on findings."],learning:["Osteoporosis needs safe activity, not blanket fear-driven inactivity.","Previous fracture changes risk assessment and exercise adaptation.","New focal pain after minor trauma requires medical assessment."],references:[nice("Osteoporosis: assessing the risk of fragility fracture (CG146)","https://www.nice.org.uk/guidance/cg146/chapter/recommendations"),jn("Osteoporosis exercise and falls prevention guideline","osteoporosis exercise recommendations resistance balance fracture prevention guideline")]}
];

export const curatedEpisodes:Record<string,CaseStory>=Object.fromEntries(episodes.map((e)=>[e.id,{
 id:e.id,category:e.category,patient:e.patient,opening:e.opening,scene:e.scene,
 history:e.history,bestHistory:0,findings:e.findings,examPrompt:e.examPrompt,
 examChoices:[],examCorrect:-1,examReason:e.examReason,
 diagnosisPrompt:"Which working diagnosis or clinical priority best fits the full history, examination and safety screen?",
 diagnosisChoices:[e.diagnosis,...e.differentials.map(d=>d.diagnosis)],diagnosisCorrect:0,
 diagnosisReason:e.diagnosisReason,differentials:e.differentials,management:e.management,
 progression:e.progression,learning:e.learning,urgent:!!e.urgent,fullyAuthored:true,
 references:e.references,teachingDiagnosis:e.diagnosis
}]));
